QCU_T("es", "histoireKine", {
  "0": ["¿Qué tipo de medio utiliza la fisioterapia como herramienta terapéutica?",["Los agentes físicos","Los agentes farmacológicos","Los agentes quirúrgicos"],["El curso define la fisioterapia como el uso de agentes físicos como medio terapéutico.","El curso califica por el contrario a la fisioterapia de « terapéutica sin medicamentos ».","La cirugía no pertenece a los medios de la fisioterapia, que se basa en agentes físicos."]],
  "1": ["Etimológicamente, ¿qué significa « agente físico »?",["Lo que actúa en la naturaleza","Lo que cura mediante la palabra","Lo que mide el dolor"],["El curso precisa: agente = « lo que actúa », físico = « de la naturaleza ».","La etimología remite a la acción en la naturaleza, no a la comunicación.","El agente físico es una herramienta de acción terapéutica, no un instrumento de medida."]],
  "2": ["Entre las categorías de agentes físicos, ¿cuál corresponde al movimiento?",["Los agentes cinéticos","Los agentes elementales","Los agentes electromagnéticos"],["El curso clasifica el movimiento (movilizaciones, trabajo activo, vibraciones) entre los agentes cinéticos.","Los agentes elementales son los de la naturaleza: calor, frío, agua, sol, tierra, sonido.","Los agentes electromagnéticos agrupan los recursos eléctricos y las radiaciones no ionizantes."]],
  "3": ["Según el curso, ¿a qué corresponden los agentes físicos llamados « elementales »?",["Los que se encuentran en la naturaleza","Las corrientes eléctricas de todas sus formas","Las movilizaciones y el trabajo activo"],["El curso los define como el calor, el frío, el agua, el sol, la tierra y el sonido presentes en la naturaleza.","Esos recursos eléctricos corresponden a los agentes electromagnéticos.","El movimiento y las movilizaciones corresponden a los agentes cinéticos."]],
  "4": ["¿Cómo califica el curso a la fisioterapia en cuanto a su naturaleza?",["Una ciencia y un arte del tratamiento físico","Una especialidad quirúrgica de rehabilitación","Una rama de los cuidados de enfermería"],["El curso define la fisioterapia como « la ciencia y el arte del tratamiento físico ».","La fisioterapia no es una especialidad quirúrgica, sino un tratamiento mediante agentes físicos.","El curso insiste: fisioterapia ≠ cuidados de enfermería."]],
  "5": ["¿Por qué se considera también la fisioterapia como un « arte »?",["Exige competencias prácticas, creativas y humanas adaptadas a cada paciente","Se basa únicamente en la aplicación de protocolos estandarizados","Corresponde a la producción de obras estéticas"],["El curso cita destreza manual, personalización, empatía y creatividad.","Al contrario, el arte implica la personalización del tratamiento, no su estandarización.","El término « arte » remite aquí a las competencias clínicas, no a la estética."]],
  "6": ["¿Cuál es el fin último de la fisioterapia según el curso?",["Mejorar la calidad de vida y facilitar la reintegración social","Establecer el diagnóstico etiológico de las enfermedades","Prescribir los tratamientos farmacológicos adecuados"],["El curso busca promover la salud para mejorar la calidad de vida y la plena reintegración social.","El diagnóstico etiológico corresponde a la CIE; el fin es funcional y social.","La fisioterapia es una terapéutica sin medicamentos."]],
  "7": ["Según el marco teórico actual del curso, la fisioterapia es una profesión:",["Independiente, que no requiere la supervisión de otros profesionales","Subordinada de forma permanente al médico rehabilitador","Vinculada jerárquicamente a los cuidados de enfermería"],["El resumen del curso la presenta como una profesión independiente no supervisada.","El curso afirma que el fisioterapeuta no depende del médico rehabilitador.","El curso distingue claramente fisioterapia y cuidados de enfermería."]],
  "8": ["¿En qué año adoptó la OMS la CIF, clasificación del funcionamiento, de la discapacidad y de la salud?",["En 2001","En 1980","En 1968"],["El curso indica que la CIF fue adoptada en 2001 por la OMS.","1980 corresponde a la antigua CIDDM, de la que la CIF es la evolución.","1968 es la fecha de la definición de la fisioterapia por la OMS, no de la CIF."]],
  "9": ["¿Qué clasifica principalmente la CIF?",["El funcionamiento y la discapacidad relacionados con la salud","Las enfermedades según su etiología","A los individuos según su discapacidad"],["El curso precisa que la CIF describe el funcionamiento humano y no las etiologías.","Son los estados de salud los que se clasifican por etiología en la CIE-11, no en la CIF.","El curso subraya que la CIF no clasifica personas, sino estados de salud."]],
  "10": ["Según el curso, ¿cómo se define una ciencia?",["Un conocimiento asociado a un método","Una opinión compartida por una mayoría de expertos","Una creencia transmitida de generación en generación"],["El curso resume: Ciencia = Conocimiento + Método.","La ciencia se basa en un método verificable, no en un consenso de opiniones.","El curso opone el conocimiento científico al conocimiento espontáneo de la vida diaria."]],
  "11": ["¿Cuáles son las características fundamentales del conocimiento científico según el curso?",["Objetividad, racionalidad y sistematicidad","Subjetividad, intuición y espontaneidad","Creatividad, empatía y comunicación"],["El curso cita exactamente esas tres características fundamentales.","Son los rasgos del conocimiento cotidiano, opuesto al conocimiento científico.","Esas cualidades corresponden al « arte » de la fisioterapia, no a los criterios de cientificidad."]],
  "12": ["¿En qué consiste la práctica basada en la evidencia en fisioterapia?",["Integrar la experiencia clínica con las mejores pruebas científicas y las preferencias del paciente","Aplicar únicamente la experiencia personal del profesional","Seguir exclusivamente las indicaciones de un superior jerárquico"],["El curso define la PBE por la integración de la experiencia clínica, las pruebas y el paciente.","La PBE va más allá de la sola experiencia al añadirle las pruebas científicas y el paciente.","La PBE se basa en las pruebas y en la decisión clínica compartida, no en la jerarquía."]],
  "13": ["¿Qué pueblo de la Antigüedad inventó la escritura cuneiforme, grabada en tablillas de arcilla?",["Los sumerios","Los egipcios","Los aztecas"],["El curso indica que los sumerios (3500-2000 a. C.) inventaron la escritura cuneiforme grabada en tablillas de arcilla.","El Egipto antiguo se asocia a las primeras terapias manuales y al papiro de Edwin Smith, no a la escritura cuneiforme.","Las civilizaciones precolombinas empleaban duchas de vapor seguidas de frío, pero no la escritura cuneiforme."]],
  "14": ["Según el curso, ¿quién se presenta como el primer médico conocido, autor del papiro de Edwin Smith?",["Imhotep","Hipócrates","Galeno"],["El curso atribuye el papiro de Edwin Smith a Imhotep, presentado como el primer médico conocido.","Hipócrates es el « Padre de la medicina » en la Grecia antigua, posterior a Imhotep.","Galeno es un médico de la Roma antigua; no redactó el papiro de Edwin Smith."]],
  "15": ["En el Egipto antiguo, ¿cómo recomendaba el papiro de Edwin Smith emplear el frío?",["En las etapas iniciales de la inflamación","Para la tonificación muscular diaria","En las etapas tardías de la cicatrización"],["El curso precisa que el frío se empleaba en las etapas iniciales de la inflamación, y el calor en las más tardías.","La tonificación mediante baño (frío/caliente) corresponde a Asclepíades de Bitinia en Grecia, no al papiro egipcio.","Según el curso, es el calor el que se empleaba en las etapas más tardías, no el frío."]],
  "16": ["En la China antigua, ¿a qué personaje se atribuye el libro de medicina « Nei-Ching »?",["El emperador Amarillo Huangdi","Tzu Kuo Shih","Chu'n Yu"],["El curso indica que el emperador Amarillo Huangdi (2697-2597 a. C.) escribió el « Nei-Ching ».","Tzu Kuo Shih escribió sobre la terapia QiGong, no el Nei-Ching.","Chu'n Yu redactó un compendio de observaciones médicas, pero no el Nei-Ching."]],
  "17": ["Según el « Nei-Ching » presentado en el curso, la enfermedad corresponde a un desequilibrio entre:",["el Yin y el Yang","los cuatro humores del cuerpo","el cuerpo y el espíritu según Descartes"],["El curso indica que la enfermedad es un desequilibrio entre el Yin y el Yang, y que el masaje restablece ese equilibrio.","La teoría de los cuatro humores corresponde al Corpus hipocrático griego, no al Nei-Ching chino.","La separación cuerpo/espíritu remite a Descartes (Renacimiento), no al Nei-Ching."]],
  "18": ["¿Qué terapia de la India antigua se presenta en el curso como próxima a la fisioterapia?",["El yoga","La acupuntura","La hidroterapia termal"],["El curso presenta el yoga como la principal aportación de la época, una terapia que se aproximaría a la fisioterapia.","La acupuntura se asocia a la China antigua (Tzu Kuo Shih), no a la India.","La hidroterapia termal la desarrolla sobre todo Asclepíades en Grecia, no la India antigua."]],
  "19": ["¿Cómo se apoda a Hipócrates en el curso?",["El Padre de la medicina","El Padre de la osteopatía","El Padre de la gimnasia sueca"],["El curso designa a Hipócrates de Cos como el « Padre de la medicina ».","El padre de la osteopatía es Andrew Taylor Still (siglo XX), no Hipócrates.","El padre de la gimnasia sueca es Pehr Henrik Ling (siglo XIX)."]],
  "20": ["¿En qué teoría se basa la concepción de la salud en el Corpus hipocrático?",["La teoría de los cuatro humores","La teoría del Yin y del Yang","La teoría de la energía meridional"],["El curso indica que la salud está ligada al equilibrio de los cuatro humores: sangre, bilis negra, bilis amarilla y flema.","El Yin y el Yang corresponden a la medicina china (Nei-Ching), no al Corpus hipocrático.","El flujo meridiano (energía vital) es propio de la acupuntura, no del Corpus hipocrático."]],
  "21": ["En la Edad Media, ¿cuál era la situación del ejercicio físico según el curso?",["Estaba prohibido, pues el culto al alma primaba sobre el del cuerpo","Era obligatorio en las escuelas","Se clasificaba según la duración y la intensidad"],["El curso indica una interrupción del ejercicio físico, prohibido porque el culto al alma es más importante que el del cuerpo.","La enseñanza obligatoria de la gimnasia en las escuelas es obra de Ling en el siglo XIX, no de la Edad Media.","La clasificación por duración e intensidad es la de Diocles de Caristo en la Grecia antigua."]],
  "22": ["¿Quién se considera en el curso el fundador de la anatomía moderna en el Renacimiento?",["Andrés Vesalio","Ambroise Paré","Nicolas Andry de Bois-Regard"],["El curso indica que Andrés Vesalio (1514-1564) se considera el fundador de la anatomía moderna.","Ambroise Paré desarrolló la primera prótesis de pierna, pero no se cita como fundador de la anatomía moderna.","Nicolas Andry introdujo la palabra « Ortopedia »; no es el fundador de la anatomía moderna."]],
  "23": ["¿Quién introdujo la palabra « Ortopedia » según el curso?",["Nicolas Andry de Bois-Regard","Francisco Arceo","Joseph Clément Tissot"],["El curso indica que Nicolas Andry de Bois-Regard (1658-1742) introdujo la palabra Ortopedia (orthos paidos; recto niño).","Francisco Arceo inventó la bota ortopédica para el pie equinovaro, pero no introdujo la palabra Ortopedia.","Tissot insistía en el ejercicio como alternativa a la cirugía; no introdujo la palabra Ortopedia."]],
  "24": ["¿Quién se presenta en el curso como el padre de la Gimnasia Sueca?",["Pehr Henrik Ling","Gustav Zander","Vincenz Priessnitz"],["El curso designa a Pehr Henrik Ling (1776-1839) como el padre de la Gimnasia Sueca (ejercicios en el suelo).","Gustav Zander es el inventor de la mecanoterapia, no de la gimnasia sueca.","Priessnitz se considera el padre de la hidroterapia, no de la gimnasia sueca."]],
  "25": ["En 1845, ¿quién propone la palabra « Kinesiterapia » para designar el tratamiento de las enfermedades mediante el movimiento?",["Georgii","Gustav Zander","Duchenne de Boulogne"],["El curso indica que en 1845 Georgii propone la palabra Kinesiterapia en su libro sobre el tratamiento mediante el movimiento según el método de Ling.","Zander inventó la mecanoterapia y sus aparatos; no propuso la palabra Kinesiterapia.","Duchenne de Boulogne trabajaba sobre la faradización localizada; no propuso el término Kinesiterapia."]],
  "26": ["¿Quién es el inventor de la mecanoterapia y de sus 71 aparatos según el curso?",["Gustav Zander","Johan Georg Metzger","Just Lucas Championnière"],["El curso indica que Gustav Zander (1835-1920) es el inventor de la mecanoterapia, con 71 aparatos clasificados en 4 categorías.","Metzger se asocia al tratamiento mediante fricciones y masaje de los esguinces, no a la mecanoterapia.","Championnière recomendaba movilizaciones activas de las articulaciones adyacentes a una fractura; no inventó la mecanoterapia."]],
  "27": ["Según el curso, ¿en qué año se creó en Francia el diploma estatal de fisioterapeuta?",["El 30 de abril de 1946","En 1900","En 1951"],["El curso indica que el 30 de abril de 1946 se crea el diploma estatal de fisioterapeuta, en sustitución de la especialidad de enfermero-masajista.","En 1900 se crea la Sociedad de Kinesiterapia en Francia, no el diploma estatal.","1951 corresponde a la creación de la WCPT, no al diploma estatal francés de fisioterapeuta."]],
  "28": ["¿Qué enfoque se caracteriza por la integración de distintas disciplinas en la resolución de un problema?",["El enfoque interdisciplinar","El enfoque multidisciplinar","El enfoque tangencial"],["El curso lo define por la integración de distintas disciplinas en la resolución de un problema.","Hace trabajar varias disciplinas en paralelo sobre el mismo caso, sin integración profunda de los conocimientos.","Es un tipo de interdisciplinariedad en el que las disciplinas están en contacto pero conservan sus límites, no un enfoque de trabajo."]],
  "29": ["En el enfoque multidisciplinar, ¿cómo trabajan las distintas disciplinas sobre un mismo caso?",["En paralelo, cada una con su propia metodología y su propia visión","Integrando sus saberes para resolver juntas el problema","Tomando prestadas recíprocamente sus leyes para crear una nueva disciplina"],["El curso indica que trabajan en paralelo sin permitir una integración profunda de los conocimientos.","Es la característica del enfoque interdisciplinar, no del multidisciplinar.","Eso describe la relación total o estructural de la interdisciplinariedad."]],
  "30": ["Según el curso, ¿a qué tipo de interdisciplinariedad corresponde la fisioterapia, que se desarrolla a partir de la estructura de otras disciplinas?",["La relación total o estructural","La relación parcial o lineal","La relación tangencial"],["El curso cita la fisioterapia como ejemplo de relación total: varias disciplinas contribuyen a crear una nueva disciplina.","Corresponde a una disciplina que toma prestada una ley de otra para explicar un fenómeno.","Designa disciplinas en contacto que conservan sus límites, como la fisiología y la anatomía."]],
  "31": ["Según el curso, ¿qué riesgo puede conllevar la especialización excesiva?",["El aislamiento profesional en « silos » de conocimiento","La desaparición definitiva de las fronteras entre disciplinas","La pérdida de experiencia del investigador en su ámbito"],["El curso indica que la especialización puede conducir al aislamiento profesional en « cabañas » o « silos ».","La desaparición de las fronteras se presenta como un factor que favorece la interdisciplinariedad, no como un riesgo de la especialización.","Al contrario, la especialización permite al investigador convertirse en experto según el curso."]],
  "32": ["Según el curso, ¿con qué finalidad aparecieron los primeros programas de tratamiento del dolor en los años 1970?",["Atender a los veteranos de guerra","Formar a los fisioterapeutas en prevención","Reducir los costes hospitalarios"],["El curso precisa que esos primeros programas buscaban atender a los veteranos de guerra.","El curso no asocia esos programas a la formación de los fisioterapeutas.","El objetivo citado es la atención a los veteranos, no una finalidad económica."]],
  "33": ["¿Cuáles son las tres dimensiones del modelo biopsicosocial?",["Biológica, psicológica y social","Biológica, motora y ambiental","Física, espiritual y económica"],["El curso presenta el modelo con las dimensiones bio, psico y social.","Esas dimensiones no corresponden al modelo biopsicosocial del curso.","El modelo del curso se basa en lo biológico, lo psicológico y lo social."]],
  "34": ["Según el curso, ¿en qué se centran los « profesionales de la salud » que no tienen necesariamente una formación en el ámbito sanitario?",["La promoción de la salud y la prevención de las enfermedades mediante la educación","El diagnóstico y el tratamiento de las patologías","La inscripción en el registro nacional de profesionales sanitarios"],["El curso indica que se centran en la promoción y la prevención mediante la educación y el empoderamiento de las comunidades.","Esos actos corresponden a los profesionales sanitarios regulados y cualificados en el ámbito de la salud.","La inscripción en el registro atañe a los profesionales sanitarios regulados, no a esos perfiles."]],
  "35": ["¿Cómo define el curso la anamnesis (entrevista clínica)?",["Un instrumento de recogida de datos basado en una comunicación interpersonal de doble sentido","Una simple conversación informal con el paciente","Una exploración física estandarizada del paciente"],["El curso la presenta como un instrumento de recogida de datos que exige una comunicación interpersonal de doble sentido.","El curso precisa explícitamente que no se trata de una simple conversación.","La exploración física es distinta de la anamnesis, que es una entrevista de recogida de datos."]],
  "36": ["Entre los objetivos de la entrevista clínica, ¿cuál figura en el curso?",["Establecer una buena relación terapéutica","Prescribir directamente un tratamiento farmacológico","Sustituir la exploración física del paciente"],["El curso cita el establecimiento de una buena relación terapéutica entre los objetivos de la entrevista.","La prescripción farmacológica no figura entre los objetivos de la entrevista clínica.","La entrevista completa la recogida de datos con otros métodos; no los sustituye."]],
  "37": ["Entre las actitudes básicas del terapeuta que favorecen la relación, ¿cuál se cita en el curso?",["La escucha activa","La máxima directividad","La simpatía hacia el paciente"],["El curso enumera la escucha activa entre las actitudes básicas que favorecen la relación, junto con la empatía, la aceptación incondicional y la autenticidad.","El curso indica que tanto el exceso como la falta de directividad son negativos.","El curso distingue la empatía de la simpatía; no cita la simpatía como actitud básica."]],
  "38": ["Según el curso, ¿en qué se distingue la empatía de la simple escucha activa?",["La empatía presupone la escucha activa pero va más allá, hasta comprender el sentido más allá de lo que el paciente expresa","La empatía consiste solo en reformular lo que dice el paciente","La empatía se limita a sentir la misma emoción que el paciente"],["El curso precisa que la empatía presupone una escucha activa pero va más allá.","La reformulación corresponde a la paráfrasis, una habilidad de escucha, no a la empatía.","El curso distingue la empatía de la simpatía y de la compasión."]],
  "39": ["¿Qué tipo de entrevista clínica se considera que ofrece un grado aceptable de flexibilidad conservando una uniformidad suficiente?",["La entrevista semiestructurada","La entrevista estructurada","La entrevista no estructurada"],["El curso indica que las entrevistas semiestructuradas ofrecen flexibilidad y una uniformidad suficiente para interpretaciones coherentes.","Aplica rigurosamente preguntas predefinidas, con el inconveniente de una falta de flexibilidad.","Es muy flexible, pero puede dejar lagunas en las informaciones necesarias."]],
  "40": ["¿Qué se pide al paciente que haga en el « mapa corporal » durante la recogida de datos?",["Dibujar las zonas de dolor, de parestesia, de quemazón o de hormigueo","Anotar la lista de sus medicamentos y alergias","Valorar él mismo su fuerza muscular"],["El curso indica que se pide al paciente dibujar esas zonas con distintos códigos o colores.","Los medicamentos y las alergias son datos recogidos aparte, no en el mapa corporal.","Las pruebas musculares corresponden a la exploración que realiza el terapeuta, no al mapa corporal."]],
  "41": ["¿Cómo se define el razonamiento clínico en fisioterapia?",["Un proceso de reflexión y de toma de decisiones que estructura el sentido y las estrategias de atención a partir de los datos clínicos y de la elección del paciente","La aplicación estricta de un protocolo estandarizado idéntico para todos los pacientes con el mismo diagnóstico","La memorización de los conocimientos biomédicos adquiridos durante la formación inicial"],["El curso define el razonamiento clínico como un proceso de reflexión o de toma de decisiones asociado a la práctica profesional, que estructura el sentido y las estrategias de tratamiento.","El curso insiste al contrario en la adaptación a cada sujeto; los protocolos rígidos son un factor limitante, no una definición del razonamiento.","La base de conocimientos es un simple elemento del proceso, no la definición del razonamiento clínico en sí."]],
  "42": ["El razonamiento clínico en fisioterapia se describe como un proceso que es:",["Complejo, cognitivo, interactivo y multifactorial","Simple, lineal e independiente del contexto","Puramente automático y siempre consciente"],["El curso califica el razonamiento clínico de complejo, cognitivo, interactivo, imperceptible y multifactorial, dependiente del contexto.","El curso precisa al contrario que depende del contexto y que es multifactorial, por tanto ni simple ni lineal.","El curso indica que no siempre es consciente ni automático; esa formulación es inexacta."]],
  "43": ["En el razonamiento inductivo se procede:",["De algo específico hacia algo general","De algo general hacia algo específico","Autorregulando sus propios pensamientos de manera reflexiva"],["El curso define el razonamiento inductivo como el que parte de lo específico para llegar a lo general, difícil de poner en práctica.","Es la definición del razonamiento deductivo, no del inductivo, según el curso.","Se trata de la metacognición, otro proceso descrito aparte en el curso."]],
  "44": ["Según el curso, ¿cuál es la evolución típica del razonamiento con la experiencia profesional?",["Se empieza por un razonamiento deductivo que se automatiza progresivamente hacia un razonamiento casi inductivo","Se empieza por un razonamiento inductivo que se vuelve progresivamente deductivo","El modo de razonamiento permanece estrictamente idéntico a lo largo de toda la carrera"],["El curso indica que se empieza por el deductivo y que después se automatiza hasta pasar a un razonamiento inductivo casi sin darse cuenta.","El curso describe la evolución inversa: del deductivo hacia el inductivo automatizado.","El curso subraya al contrario una transformación progresiva ligada a la experiencia."]],
  "45": ["En el proceso de razonamiento, ¿a qué corresponde la metacognición?",["Al proceso de autorregulación del clínico que reflexiona sobre sus propios pensamientos de forma escéptica","A la percepción, el análisis, la síntesis y la evaluación de los datos recogidos","Al conjunto de los conocimientos biomédicos adquiridos durante la formación"],["El curso define la metacognición como la autorregulación del clínico para elaborar sus pensamientos de manera escéptica y reflexiva (pensar sobre sus pensamientos).","Esa descripción corresponde a la cognición, no a la metacognición, según el curso.","Se trata de la base de conocimientos, distinta de la metacognición en el curso."]],
  "46": ["¿En qué tipo de razonamiento se fundamenta el modelo inicial del razonamiento clínico?",["Un razonamiento hipotético-deductivo procedente del paradigma de las ciencias cognitivas","Un enfoque colaborativo centrado en las ciencias del dolor","Una interacción multidimensional entre factores biológicos, psicológicos y sociales"],["El curso indica que el modelo inicial se basa en el paradigma de las ciencias cognitivas y se caracteriza por un razonamiento hipotético-deductivo.","Es el modelo de razonamiento clínico colaborativo, no el modelo inicial.","Esa descripción corresponde al modelo biopsicosocial, no al modelo inicial."]],
  "47": ["¿Cómo describe el modelo biopsicosocial el dolor y la discapacidad?",["Como una interacción multidimensional y recíproca entre factores biológicos, psicológicos y sociales","Como el resultado directo y único de una lesión tisular objetivada en las pruebas complementarias","Como un fenómeno determinado principalmente por la colaboración entre profesionales"],["El curso describe el enfoque biopsicosocial como una interacción multidimensional, dinámica e inseparable entre factores biológicos, psicológicos y sociales.","Esa sería una visión puramente biomédica; el modelo biopsicosocial integra también lo psicológico y lo social.","El modelo biopsicosocial versa sobre la interacción de tres factores, no sobre la colaboración interprofesional."]],
  "48": ["En el modelo biopsicosocial, ¿a qué factor corresponden la kinesiofobia y el catastrofismo?",["Al factor psicológico","Al factor biológico","Al factor social"],["El curso clasifica los factores psicológicos (estrategias de afrontamiento, kinesiofobia, catastrofismo, depresión, ansiedad) en la dimensión psico.","El factor bio atañe a la nocicepción, la inflamación y las pruebas de imagen, no a la kinesiofobia.","El factor social atañe al condicionamiento cultural y a los acontecimientos vitales estresantes, no al catastrofismo."]],
  "49": ["¿Cuál es el objetivo principal de la exploración subjetiva?",["Definir el origen del problema, identificar las señales de alarma y orientar la evaluación","Confirmar o descartar las hipótesis mediante pruebas físicas específicas","Realizar una exploración física exhaustiva para reproducir los síntomas"],["El curso precisa que la exploración subjetiva busca definir el origen del problema, identificar las señales de alarma, el pronóstico y orientar las pruebas funcionales.","Es un objetivo de la exploración objetiva, que viene a reproducir las manifestaciones clínicas mediante pruebas.","La exploración física exhaustiva corresponde a la exploración objetiva, no a la subjetiva."]],
  "50": ["¿Qué elemento constituye un indicador de alarma (bandera roja) en la exploración subjetiva?",["Un dolor nocturno intenso que no se modifica con los medicamentos ni con la postura","Un dolor mecánico que empeora con el movimiento y mejora con el reposo","Un dolor intermitente de intensidad leve aparecido tras un esfuerzo"],["El curso cita el dolor nocturno intenso y el dolor no modificado por medicamentos ni postura entre las banderas rojas.","Ese comportamiento es típicamente mecánico y tranquilizador, no una bandera roja según el curso.","Un dolor leve e intermitente no figura entre los indicadores de alarma del curso."]],
  "51": ["Según el sistema de categorización de las hipótesis, ¿a qué corresponde la hipótesis de pronóstico?",["Explicar al paciente, en forma de hipótesis, la duración probable del proceso de curación","Identificar las precauciones y contraindicaciones para la exploración y el tratamiento","Determinar los mecanismos patobiológicos como la inflamación o la nocicepción"],["El curso define la hipótesis de pronóstico como la estimación, explicada al paciente, de la duración del proceso de curación, sin prometer nunca el 100 %.","Eso corresponde a la hipótesis de precauciones y contraindicaciones, una categoría distinta.","Es la hipótesis de los mecanismos patobiológicos, no la hipótesis de pronóstico."]],
  "52": ["Sobre el sistema musculoesquelético, ¿cuál es un efecto del ejercicio terapéutico?",["Aumento de la masa ósea, que previene la osteoporosis","Engrosamiento del cartílago articular por aporte de colágeno","Acortamiento adaptativo de los tendones más solicitados"],["El curso cita el aumento de la masa ósea, que previene la osteoporosis, entre los efectos musculoesqueléticos.","El curso no describe ningún engrosamiento del cartílago: los efectos musculoesqueléticos que recoge atañen al hueso, al músculo y a la movilidad.","No se describe ningún acortamiento tendinoso: la carga de entrenamiento no se presenta como una exigencia de retracción."]],
  "53": ["¿Qué efecto cardiovascular produce el ejercicio terapéutico a largo plazo?",["Reducción de la frecuencia cardiaca basal","Aumento permanente de la presión arterial basal","Disminución de la capacidad aerobia"],["El ejercicio sistemático produce adaptaciones que reducen la frecuencia cardiaca basal.","El aumento de la presión es solo un efecto a corto plazo, no una adaptación duradera.","El curso describe un aumento de la capacidad aerobia y de la resistencia."]],
  "54": ["¿Cómo actúa el ejercicio terapéutico sobre el dolor (sistema neuromuscular)?",["Libera endorfinas y activa los controles central y periférico del dolor","Aumenta la inflamación local para enmascarar el dolor","Bloquea definitivamente la conducción de las fibras nociceptivas"],["El curso cita la liberación de endorfinas y la activación de los mecanismos centrales y periféricos.","El curso indica una reducción de la inflamación, no un aumento.","El efecto es una hipoalgesia transitoria, no un bloqueo definitivo de las fibras."]],
  "55": ["¿Cuál es el objetivo principal del masaje sedante o relajante?",["Sedar el dolor actuando sobre las terminaciones nerviosas de la piel","Recuperar el tono, el volumen y la fuerza muscular","Estimular los sistemas nervioso y circulatorio"],["El curso define ese masaje como aquel que seda el dolor a través de las terminaciones nerviosas cutáneas.","Es el objetivo del masaje tonificante, no del sedante.","Es el objetivo del masaje estimulante."]],
  "56": ["¿Cuál es el efecto del drenaje linfático manual?",["Activación del flujo linfático y reabsorción del líquido intersticial","Aumento de la acción del sistema nervioso simpático","Aumento de la frecuencia cardiaca"],["El curso describe la movilización del líquido intersticial y la activación del flujo linfático.","El curso indica una reducción de la acción simpática (relajación).","El curso describe una disminución de la frecuencia cardiaca (efecto parasimpático)."]],
  "57": ["Según los grados de Maitland, ¿cuál es el objetivo de una movilización de grado I?",["Reducir el dolor y desensibilizar la articulación en los estados irritables","Ganar los últimos grados de movilidad capsular","Aumentar la movilidad cuando predomina la rigidez"],["El grado I (pequeña amplitud, inicio del recorrido) busca disminuir el dolor y desensibilizar.","Es el objetivo del grado IV (pequeña amplitud al final del recorrido).","Es el objetivo del grado III (gran amplitud hasta la barrera)."]],
  "58": ["Según la teoría de la compuerta, ¿qué fibras se estimulan para inhibir la transmisión del dolor?",["Las fibras A-beta del tacto y de la presión","Las fibras A-delta del dolor agudo","Las fibras C del dolor sordo"],["El curso indica que las fibras A-beta, de gran diámetro, del tacto y de la presión, activan la interneurona inhibidora del asta dorsal y cierran así la compuerta al dolor.","Las fibras A-delta transmiten el dolor agudo; no cierran la compuerta.","Las fibras C transmiten el dolor sordo y continuo; no inhiben la transmisión."]],
  "59": ["En electroterapia, ¿con qué finalidad se emplean las altas frecuencias (superiores a 50 Hz)?",["La analgesia","La electroestimulación muscular","La producción de una corriente galvánica continua"],["El curso precisa que las altas frecuencias (>50 Hz) se emplean para la analgesia.","El curso reserva las bajas frecuencias (<50 Hz) a la electroestimulación.","La corriente galvánica es una corriente continua a 0 Hz, sin relación con la elección de frecuencia."]],
  "60": ["¿Qué tejidos se consideran buenos conductores de la corriente eléctrica?",["La sangre, la linfa y el músculo","El hueso, la grasa y la piel callosa","Los tendones, las fascias y el cartílago"],["El curso clasifica la linfa, la sangre y los músculos entre los buenos conductores (ricos en agua y electrolitos).","El curso los clasifica entre los malos conductores.","El curso los clasifica como conductores intermedios."]],
  "61": ["¿Cuál es un efecto neuroquímico de la neuroplasticidad en fisioterapia neurológica?",["Cambios en los neurotransmisores y los receptores","La pérdida definitiva de la eficacia sináptica","La ausencia de formación de nuevas sinapsis"],["El curso cita los cambios neuroquímicos: neurotransmisores y receptores.","El curso describe una mejora de la eficacia sináptica, no su pérdida.","El curso cita al contrario la creación de nuevas sinapsis (regeneración axonal)."]],
  "62": ["¿Cómo se define la plasticidad neuronal?",["La capacidad del sistema nervioso de cambiar de función y de estructura en respuesta a los estímulos","La degradación irreversible de las conexiones neuronales tras una lesión","La transmisión fija e inmutable de los mensajes nerviosos"],["El curso define la plasticidad como ese cambio de funcionalidad y de estructura frente a los estímulos.","El curso describe una adaptación, no una degradación irreversible.","La plasticidad implica precisamente una modificación, no una transmisión inmutable."]],
  "63": ["¿Cuál es un efecto fisiológico de la fisioterapia respiratoria sobre el intercambio gaseoso?",["Mejora de la oxigenación de los tejidos y reducción de la hipercapnia","Aumento de la hiperinsuflación pulmonar","Disminución del aclaramiento mucociliar"],["El curso cita la mejora de la oxigenación y la reducción de la hipercapnia.","El curso indica al contrario una disminución de la hiperinsuflación pulmonar.","El curso busca favorecer el aclaramiento mucociliar, no disminuirlo."]],
  "64": ["¿Qué efecto fisiológico produce la fisioterapia respiratoria sobre la ventilación?",["Aumento de la ventilación alveolar","Aumento de la intensidad percibida de la disnea","Reducción de la capacidad de ejercicio"],["El curso cita el aumento de la ventilación alveolar como efecto sobre la ventilación.","El curso indica una reducción de la disnea percibida.","El curso describe una mejora de la capacidad de ejercicio."]],
  "65": ["Entre los efectos mecánicos de la punción seca, ¿cuál se describe en el curso?",["Eliminación de las sustancias sensibilizantes como la sustancia P","Descenso del pH en los puntos gatillo","Disminución de la circulación sanguínea del músculo"],["El curso cita la eliminación de las sustancias sensibilizantes (sustancia P, bradicinina).","El curso describe una elevación del pH en los puntos gatillo, no un descenso.","El curso indica una mejora de la circulación y de la oxigenación musculares."]],
  "66": ["¿Cuál es el mecanismo de acción de la electrólisis percutánea?",["Una corriente galvánica que provoca una reacción inflamatoria controlada que estimula la reparación","Una ablación térmica del tejido mediante corriente de alta frecuencia","La inyección de una sustancia analgésica a través de la aguja"],["El curso describe la aplicación de una corriente galvánica que induce una inflamación controlada reparadora.","El procedimiento es electroquímico mediante una corriente galvánica, no una ablación térmica.","No se inyecta ninguna sustancia; el efecto proviene de la corriente galvánica."]],
  "67": ["Según el curso, ¿quién realizó la primera descripción que reúne todos los medios o agentes físicos en el marco de la fisioterapia (1921)?",["Gilbert y Carnot","Max Herz","Nogier"],["El curso atribuye a Gilbert y Carnot, en 1921, la primera aglutinación de todos los agentes físicos en la fisioterapia.","Max Herz, profesor en Viena, mencionó los métodos fisioterápicos a comienzos del siglo XX, pero no esa descripción conjunta de 1921.","Nogier se cita como referencia bibliográfica (electroterapia), no como autor de esa primera descripción."]],
  "68": ["Según Max Herz, lo que caracteriza a las materias fisioterápicas no es un sistema de órganos ni un tipo de afección, sino:",["el dominio y el manejo exclusivos de una técnica terapéutica específica","la dependencia jerárquica respecto del médico","el uso exclusivo de medicamentos específicos"],["Herz define esas materias por el dominio y el manejo exclusivos de una técnica terapéutica específica.","La dependencia del médico rehabilitador se menciona en otro lugar como un freno, no como el criterio de Herz.","Al contrario, Herz habla de « terapéutica sin medicamentos » o « arte de curar sin medicamentos »."]],
  "69": ["Según el curso, ¿cómo califica Max Herz los métodos fisioterápicos en relación con los medicamentos?",["Terapéutica sin medicamentos, o arte de curar sin medicamentos","Terapéutica complementaria a los medicamentos","Terapéutica basada en los medicamentos físicos"],["Herz habla de « terapéutica sin medicamentos » o « arte de curar sin medicamentos ».","El curso no menciona una complementariedad, sino una terapéutica sin medicamentos.","El término empleado es « sin medicamentos », no « medicamentos físicos »."]],
  "70": ["Entre las categorías de agentes físicos, ¿a cuál pertenecen las corrientes alternas y continuas, los infrarrojos y el láser?",["Los agentes electromagnéticos","Los agentes cinéticos","Los agentes elementales"],["El curso clasifica los recursos eléctricos (corrientes, infrarrojos, ultravioletas, láser) entre los agentes electromagnéticos.","Los agentes cinéticos corresponden al movimiento (movilizaciones, trabajo activo), no a las corrientes y radiaciones.","Los agentes elementales son los que se encuentran en la naturaleza (calor, frío, agua), no las corrientes eléctricas."]],
  "71": ["Según el curso, los agentes físicos electromagnéticos reúnen los recursos eléctricos en todas sus formas, con excepción:",["de las radiaciones ionizantes","de las corrientes continuas","del láser"],["El curso precisa que la categoría electromagnética excluye las radiaciones ionizantes.","Las corrientes continuas forman parte de los agentes electromagnéticos; no quedan excluidas.","El láser se cita como ejemplo de agente electromagnético; no queda excluido."]],
  "72": ["Según el curso, ¿a qué ámbito no está realmente vinculada la fisioterapia, aunque ese vínculo inicial haya condicionado su desarrollo?",["Los cuidados de enfermería","La farmacología","La radiología"],["El curso indica que la fisioterapia no está vinculada a los cuidados de enfermería, pero que ese vínculo inicial condicionó su desarrollo.","El curso no menciona la farmacología como vínculo inicial que haya condicionado el desarrollo de la profesión.","El curso no menciona la radiología como vínculo histórico que haya deformado la percepción de la profesión."]],
  "73": ["Según el curso, ¿qué diferencia esencial separa al fisioterapeuta del personal de enfermería?",["El fisioterapeuta busca una respuesta orgánica de curación; la enfermería proporciona acciones que la persona no puede o no sabe hacer por sí misma","El fisioterapeuta concibe cuidados; la enfermería busca una respuesta orgánica","Ambos persiguen únicamente la misma respuesta orgánica de curación"],["El curso opone la búsqueda de una respuesta orgánica curativa (fisioterapia) al hecho de suplir a la persona (enfermería).","Es al contrario: la enfermería concibe y aplica cuidados, y el fisioterapeuta busca la respuesta orgánica.","El curso subraya al contrario una diferencia de finalidad entre ambas profesiones."]],
  "74": ["Según la ley 44/2003 citada en el curso, los tratamientos del fisioterapeuta buscan la recuperación y la readaptación de las personas que padecen:",["disfunciones somáticas o discapacidades, así como su prevención","únicamente enfermedades infecciosas agudas","exclusivamente trastornos psiquiátricos"],["La ley 44/2003 menciona las disfunciones somáticas o discapacidades y su prevención.","La ley no restringe la fisioterapia a las enfermedades infecciosas agudas.","La ley se refiere a las disfunciones somáticas o discapacidades, no exclusivamente a los trastornos psiquiátricos."]],
  "75": ["Según la definición de la OMS (1968) citada en el curso, la fisioterapia es el arte y la ciencia del tratamiento mediante:",["el ejercicio terapéutico, el calor, el frío, el agua, el masaje y la electricidad","los medicamentos y la cirugía reparadora","las radiaciones ionizantes y la radioterapia"],["La definición de la OMS (1968) enumera el ejercicio terapéutico, el calor, el frío, el agua, el masaje y la electricidad.","La OMS no menciona los medicamentos ni la cirugía en esa definición de la fisioterapia.","La OMS de 1968 no cita las radiaciones ionizantes en su definición."]],
  "76": ["Según la WCPT (1999) citada en el curso, ¿qué constituye la base de lo que se considera sano?",["Un movimiento completo y funcional","La ausencia total de todo dolor","La toma regular de tratamientos físicos"],["La WCPT (1999) considera que un movimiento completo y funcional es la base de lo que es sano.","El curso no define la salud por la ausencia de dolor, sino por el movimiento funcional.","La base admitida es el movimiento funcional, no la toma de tratamientos."]],
  "77": ["Según la definición de ciencia dada en el curso, los principios y leyes deducidos deben tener una capacidad:",["predictiva y verificable experimentalmente","intuitiva y no reproducible","subjetiva y personal"],["La definición (RAE) precisa leyes con una capacidad predictiva y verificable experimentalmente.","La ciencia exige al contrario una verificación experimental, no la intuición no reproducible.","El conocimiento científico se caracteriza por la objetividad, no por la subjetividad."]],
  "78": ["Según el curso, la característica radical de una ciencia, que permite superar un simple conocimiento superficial, es:",["el hecho de tener un método","el hecho de basarse en la intuición cotidiana","el hecho de acumular hechos sin orden"],["El curso afirma que la característica radical de la ciencia es tener un método: Ciencia = Conocimiento + Método.","El pensamiento cotidiano no busca explicaciones profundas; no es eso lo que define la ciencia.","La sistematicidad exige al contrario un conjunto ordenado y relacionado, no una acumulación sin orden."]],
  "79": ["Según el curso, ¿cuáles son los dos pilares fundamentales en los que se basa el método científico?",["La reproducibilidad y la refutabilidad","La subjetividad y la intuición","La tradición y la autoridad"],["El curso identifica la reproducibilidad y la refutabilidad como los dos pilares del método científico.","El método científico es objetivo y se basa en pruebas, no es subjetivo ni intuitivo.","El curso no fundamenta el método científico en la tradición ni en la autoridad, sino en la reproducibilidad y la refutabilidad."]],
  "80": ["Según el curso, ¿qué indicio hallado en un esqueleto prehistórico (callo óseo) se interpreta como señal de la aparición de la empatía en el ser humano?",["Una marca de reparación de fractura","Una huella de trepanación craneal","Un amuleto colocado junto al cuerpo"],["El callo óseo atestigua que un miembro del grupo ayudó al herido a recuperarse, señal de empatía.","El curso habla de un callo óseo que repara una fractura, no de una trepanación del cráneo.","Los amuletos se mencionan en la Edad Media profana, no como indicio de empatía prehistórica."]],
  "81": ["Según el curso, ¿en qué se basaba principalmente la medicina empírica aparecida en la prehistoria?",["La experiencia y la observación de efectos que parecían beneficiosos","La teoría de los cuatro humores","La lectura de textos racionales escritos"],["Empleaba agentes físicos (calor, frío, agua), basándose en la experiencia y la observación.","La teoría de los humores proviene del Corpus hipocrático en la Grecia antigua, no de la prehistoria.","La escritura aparece con los sumerios; la medicina primitiva era empírica, sin textos."]],
  "82": ["Según el curso, ¿a qué civilización antigua se atribuye el dedo gordo de Greville Chester, presentado como la primera prótesis de la historia?",["El Egipto antiguo","Los sumerios","La América precolombina"],["El dedo gordo de Greville Chester (siglo XIII a. C.) se cita para el Egipto antiguo.","Los sumerios se citan por la escritura cuneiforme y la rueda, no por esa prótesis.","Las civilizaciones precolombinas empleaban duchas de vapor y exorcismos, no esa prótesis."]],
  "83": ["Según el curso, ¿qué práctica terapéutica empleaban los aztecas (América antigua)?",["Duchas de vapor seguidas de duchas frías","Baños de mar contra las afecciones de las glándulas","Masajes con aceites aromáticos"],["El curso indica que los aztecas empleaban duchas de vapor seguidas de duchas frías.","El agua de mar contra las glándulas se atribuye a Richard Russell, en la Edad Moderna.","El masaje con aceites aromáticos corresponde a la medicina ayurvédica de la India antigua."]],
  "84": ["Según el curso, ¿a qué emperador chino se le recomendaban ejercicios respiratorios y masajes contra la fiebre, los escalofríos y la parálisis?",["El emperador Amarillo Huangdi","Chu'n Yu","Tzu Kuo Shih"],["Huangdi, autor del Nei-Ching, recomienda ejercicios respiratorios y masajes contra la fiebre, los escalofríos y la parálisis.","Chu'n Yu escribió observaciones y preguntas y respuestas de terapia física, pero no esas recomendaciones.","Tzu Kuo Shih se asocia a la terapia QiGong y a la acupuntura, no a esas recomendaciones."]],
  "85": ["Según el curso, ¿qué médico de la Roma antigua se describe como un niño prodigio que « dogmatizó » la medicina durante los 1500 años siguientes?",["Galeno","Celso","Plinio el Viejo"],["El curso presenta a Galeno como un niño prodigio que dogmatiza la medicina durante 1500 años.","Celso recomendaba movilizaciones activas y pasivas, pero no se describe así.","Plinio el Viejo defendía la helioterapia y el solárium, no la dogmatización de la medicina."]],
  "86": ["Según el curso, ¿qué principio ético fundamental se asocia al juramento hipocrático mediante la fórmula « Primum non nocere »?",["La no maleficencia (no dañar)","La confidencialidad del secreto médico","La transmisión del saber a las generaciones futuras"],["« Primum non nocere » designa la no maleficencia: no dañar al paciente.","La confidencialidad es otro principio del juramento, pero distinto de « Primum non nocere ».","La enseñanza es un principio del juramento, pero no corresponde a esa fórmula."]],
  "87": ["Según el curso, ¿qué médico de la Edad Moderna desarrolló la primera prótesis de pierna y recomendaba el masaje del muñón del amputado?",["Ambroise Paré","Francisco Arceo","Andrés Vesalio"],["Ambroise Paré desarrolló la primera prótesis de pierna y recomendaba el masaje del muñón.","Arceo inventó la bota ortopédica para el pie equinovaro, con la ayuda de Paré.","Vesalio es el fundador de la anatomía moderna, no el autor de esa prótesis."]],
  "88": ["Según el curso, ¿qué autor español de la Edad Moderna escribió el « Libro del ejercicio corporal »?",["Cristóbal Méndez","Bernardino Gómez Miedes","Sebastián Busqué y Torró"],["Méndez escribe el « Libro del ejercicio corporal », obra mayor de la terapia física en España.","Gómez Miedes escribe el Enchiridion, manual contra la gota, no ese libro.","Busqué y Torró publica una gimnasia higiénica en el siglo XIX, siguiendo a Ling."]],
  "89": ["Según el curso, ¿qué médico que trabajaba sobre el raquitismo infantil presentó la técnica de suspensión y de tracción para enderezar la columna vertebral?",["Francis Glisson","Giovanni Alfonso","Joseph Duchenne"],["Glisson, que estudiaba el raquitismo, presentó la suspensión y la tracción para enderezar el raquis.","Alfonso se interesó por el Motus y la mecánica del movimiento en « Motus Animalis ».","Joseph Duchenne afirmaba que el ejercicio previene los dolores del reposo, sin esa técnica."]],
  "90": ["Según el curso, ¿qué médico se cita como tratante de la parálisis con corrientes eléctricas y describió la evolución del hombro congelado de su vecino mediante descargas eléctricas?",["Benjamin Franklin","Luigi Galvani","Christian Gottlieb Kratzenstein"],["Franklin trata la parálisis con corrientes eléctricas y describe el hombro congelado de su vecino.","Galvani, con Volta, descubre la excitabilidad muscular mediante la electricidad, sin ese caso clínico.","Kratzenstein se cita por la recuperación de una parálisis del quinto dedo de la mano."]],
  "91": ["Según el curso, ¿a qué fisiólogo se atribuye la corriente farádica, primera corriente alterna empleada en terapia?",["Faraday","Carlo Matteucci","Duchenne de Boulogne"],["El curso indica que Faraday introduce la corriente farádica, primera corriente alterna en terapia.","Matteucci estudia la electrólisis, la electroacupuntura y la electrofisiología, no esa corriente.","Duchenne de Boulogne trabaja sobre la faradización localizada y los puntos motores."]],
  "92": ["Según el curso, ¿quién se considera el padre de la hidroterapia, que fundó un centro en 1829 para aplicar el método hidropático?",["Vincenz Priessnitz","Louis Fleury","Sigmund Hahn"],["Priessnitz, padre de la hidroterapia, funda un centro en 1829 para el método hidropático.","Fleury hizo pasar la técnica de Priessnitz de una terapia empírica a científica.","Hahn describió el efecto del agua fría sobre el cuerpo en la Edad Moderna, sin ser ese padre."]],
  "93": ["Según el curso, ¿quién se considera el « padre de la osteopatía »?",["Andrew Taylor Still","Daniel David Palmer","August Paul von Wassermann"],["El curso presenta a Andrew Taylor Still como el padre de la osteopatía, que partió de los trabajos de Hipócrates.","Palmer, magnetizador, está en el origen de la quiropraxia, no de la osteopatía.","Wassermann compiló en 1928 los agentes físicos de la historia, sin fundar la osteopatía."]],
  "94": ["Según el curso, ¿qué método de 1943 trata primero la parálisis cerebral infantil y después a los adultos hemipléjicos?",["El método Bobath","El método Vojta","El método Klapp"],["Bobath (1943) trata la parálisis cerebral infantil y después a los adultos hemipléjicos.","Vojta (1970) es un diagnóstico y tratamiento precoz basado en la estimulación refleja.","Klapp (1904) atañe a la movilización para la escoliosis, no a la parálisis cerebral."]],
  "95": ["Según el curso, ¿a qué principio deben responder las distintas disciplinas en el trabajo interdisciplinar?",["Un principio de complementariedad","Un principio de jerarquía médica","Un principio de independencia total"],["El curso indica que las disciplinas deben responder a un principio de complementariedad, aceptando las capacidades y los límites de cada una.","El curso no fundamenta la interdisciplinariedad en una jerarquía, sino en la complementariedad.","El curso precisa al contrario que eso no significa ganancia ni pérdida de independencia, sino un enriquecimiento mutuo."]],
  "96": ["Según el curso, ¿qué profesionales intervienen típicamente en un programa interdisciplinar de manejo del dolor?",["Médicos, enfermeras, psicólogos, fisioterapeutas y terapeutas ocupacionales","Únicamente médicos y farmacéuticos","Únicamente cirujanos y anestesistas"],["El curso cita a esos profesionales entre quienes participan en los programas interdisciplinares del dolor.","El curso describe un equipo multiprofesional mucho más amplio que esos dos perfiles.","Esas especialidades no son la relación que da el curso para esos programas."]],
  "97": ["Según el curso, en el modelo biopsicosocial, ¿a qué dimensión pertenece el trabajo?",["A la dimensión social","A la dimensión biológica","A la dimensión psicológica"],["El curso clasifica el trabajo, la familia y la atención sanitaria en la dimensión social.","La dimensión biológica reúne medicamentos, ejercicio, cirugías y sueño, no el trabajo.","La dimensión psicológica atañe a la cognición, las emociones, la conducta y la atención."]],
  "98": ["Según el curso, ¿en qué consiste una relación interdisciplinar de tipo « parcial o lineal »?",["Una disciplina toma prestada una ley de otra para explicar un fenómeno","Varias disciplinas se fusionan para crear una nueva disciplina","Las disciplinas se tocan pero conservan sus límites"],["El curso define la relación parcial o lineal como el préstamo de una ley de una disciplina a otra (p. ej. termodinámica, gravedad).","Eso corresponde a la relación total o estructural, no a la relación parcial.","Eso describe la relación tangencial, no la relación parcial o lineal."]],
  "99": ["Según el curso, ¿dónde se inscriben en España los profesionales sanitarios regulados y cualificados?",["En el registro nacional de profesionales sanitarios","En el registro de profesiones liberales","En el registro de educadores de salud"],["El curso indica que esas profesiones se inscriben en el registro nacional de profesionales sanitarios, lo que garantiza la validez de sus títulos.","El curso menciona específicamente el registro nacional de profesionales sanitarios.","Ese registro no se cita en el curso para los profesionales sanitarios regulados."]],
  "100": ["Según el curso, la anamnesis (entrevista clínica) requiere un proceso de comunicación que es:",["Interpersonal y de doble sentido","De sentido único, del terapeuta hacia el paciente","Puramente escrito, sin intercambio verbal"],["El curso precisa que la anamnesis requiere un proceso de comunicación interpersonal de doble sentido.","El curso insiste en el doble sentido, no en una comunicación unidireccional.","La anamnesis es un diálogo verbal, no un simple intercambio escrito."]],
  "101": ["Según el curso, ¿qué tipo de entrevista clínica aplica rigurosamente preguntas predefinidas a todos los sujetos?",["La entrevista estructurada","La entrevista semiestructurada","La entrevista no estructurada"],["El curso indica que la entrevista estructurada emplea preguntas predefinidas aplicadas rigurosamente a todos los sujetos, con objetividad y fiabilidad elevadas.","La entrevista semiestructurada parte de preguntas planificadas pero adaptables; no se aplica rigurosamente.","La entrevista no estructurada es informal y flexible, sin preguntas rigurosamente predefinidas."]],
  "102": ["Según el curso, ¿cuál es un inconveniente de la entrevista clínica no estructurada?",["Pueden quedar lagunas en las informaciones necesarias","Carece de flexibilidad y de adaptación al sujeto","Impide toda relación terapéutica"],["El curso señala que la entrevista no estructurada puede dejar lagunas en los datos por recoger.","Esa falta de flexibilidad es el inconveniente de la entrevista estructurada, no de la no estructurada.","El curso no atribuye ese inconveniente a la entrevista no estructurada."]],
  "103": ["Según el curso, ¿qué distancia se recomienda entre el fisioterapeuta y el paciente durante la entrevista?",["Unos 50 a 100 cm","Unos 10 a 30 cm","Unos 150 a 200 cm"],["El curso recomienda una distancia de unos 50 a 100 cm para preservar el « espacio burbuja » sin dar una sensación de frialdad.","Esa distancia sería demasiado corta e invadiría el espacio personal del paciente.","Esa distancia daría una sensación de frialdad o de desinterés según la lógica del curso."]],
  "104": ["Entre las actitudes básicas del terapeuta, ¿cómo define el curso la aceptación incondicional?",["Aceptar al paciente tal como es, sin juzgarlo, y apreciarlo como persona","Sentir la misma emoción que el paciente ante su problema","Comunicar sus propios sentimientos con sinceridad"],["El curso define la aceptación incondicional como aceptar al paciente sin juicio y apreciarlo como persona.","Eso se aproxima a la simpatía, distinta de la aceptación incondicional.","Eso corresponde a la autenticidad, otra actitud básica distinta."]],
  "105": ["Según el curso, ¿en qué consiste la habilidad de « clarificación » en la escucha?",["Pedir al paciente que precise el sentido de un mensaje vago o ambiguo","Resumir en otros términos el contenido principal del mensaje","Expresar los sentimientos del paciente, sean explícitos o implícitos"],["El curso define la clarificación como pedir al paciente que aclare un mensaje vago, ambiguo o implícito.","Eso corresponde a la paráfrasis, no a la clarificación.","Eso corresponde al reflejo, no a la clarificación."]],
  "106": ["Según el curso, ¿qué debe hacerse cuando una persona expone un problema por primera vez?",["Dejarla expresarse sin interrumpirla con peticiones frecuentes de aclaración","Formular de inmediato hipótesis firmes para ganar tiempo","Responder por anticipado a las informaciones aún no comunicadas"],["El curso aconseja dejar que el paciente se exprese y no interrumpirlo con peticiones frecuentes de clarificación en una primera exposición.","El curso cita al contrario la formulación de hipótesis firmes con pocos datos como un obstáculo para la escucha.","El curso presenta esa conducta como un obstáculo para una escucha eficaz."]],
  "107": ["Según el curso, en el « mapa corporal », ¿con qué códigos marca el paciente las zonas afectadas?",["Distintos códigos o colores según el tipo de síntoma","Únicamente una cruz negra sobre cada zona dolorosa","Cifras del 1 al 10 que indican la frecuencia horaria"],["El curso pide al paciente dibujar las zonas de dolor, parestesia, quemazón u hormigueo con distintos códigos o colores.","El curso prevé códigos o colores variados, no una marca única.","El curso no emplea una escala horaria numerada en el mapa corporal."]],
  "108": ["En el razonamiento deductivo se procede:",["de lo general hacia lo específico","de lo específico hacia lo general","sin punto de partida definido"],["El curso indica que el razonamiento deductivo parte de algo muy general para llegar a algo específico.","Es la definición del razonamiento inductivo, no del deductivo.","El razonamiento deductivo sí tiene un punto de partida general identificado."]],
  "109": ["Según el curso, ¿qué tipo de razonamiento se describe como muy complicado y difícil de poner en práctica?",["El razonamiento inductivo","El razonamiento deductivo","El razonamiento analógico"],["El curso califica el razonamiento inductivo (de lo específico a lo general) de muy complicado y muy difícil de poner en práctica.","El deductivo se presenta como el punto de partida habitual, no como el más difícil.","Ese tipo no se cita como el más difícil en el curso."]],
  "110": ["Según el curso, la experiencia en materia de razonamiento clínico:",["no se limita al número de años de trabajo","equivale al número de años de trabajo","depende únicamente de la frecuencia de las decisiones"],["El curso precisa que la experiencia no se limita al número de años de trabajo ni a la frecuencia de la toma de decisiones.","El curso dice precisamente lo contrario: no se reduce a los años de ejercicio.","El curso indica que no es sinónimo de una mayor frecuencia en la toma de decisiones."]],
  "111": ["Entre los posibles prejuicios del fisioterapeuta, ¿cuál se cita en el curso?",["El sesgo de confirmación","El sesgo de disponibilidad","El sesgo de anclaje"],["El curso enumera el sesgo de confirmación entre los prejuicios ligados a las creencias del fisioterapeuta.","Ese sesgo no se cita en la relación del curso.","Ese sesgo no se menciona entre los prejuicios enumerados por el curso."]],
  "112": ["En el factor PSICO del modelo biopsicosocial, ¿qué estrategia hay que intentar favorecer siempre en el paciente?",["Estrategias de afrontamiento activas","Estrategias de afrontamiento pasivas","La evitación de la actividad"],["El curso indica que hay que intentar siempre que el paciente ponga en práctica estrategias de afrontamiento activas, por ejemplo hacer ejercicio.","El curso prioriza las estrategias activas antes que las pasivas.","La evitación corresponde al modelo miedo-evitación, una adaptación negativa que hay que evitar."]],
  "113": ["Según el curso, ¿a qué factor del modelo biopsicosocial pertenece el nivel socioeconómico del paciente?",["Al factor social","Al factor biológico","Al factor psicológico"],["El curso clasifica el estatus o nivel socioeconómico y la educación entre los factores sociales.","El factor biológico atañe a la nocicepción, la inflamación y las pruebas de imagen.","El factor psicológico reúne la kinesiofobia, el catastrofismo y la ansiedad."]],
  "114": ["Según el curso, ¿qué modelo de razonamiento clínico no se adapta a la fisioterapia porque se basa en el diagnóstico?",["El modelo inicial","El modelo colaborativo","El modelo biopsicosocial"],["El curso indica que el modelo inicial, basado en el diagnóstico y en el razonamiento hipotético-deductivo, no se adapta a la fisioterapia, cuyo razonamiento se basa en la función.","El modelo colaborativo implica al paciente e integra los factores psicosociales; no se centra en el diagnóstico.","El modelo biopsicosocial es multidimensional y el curso no lo rechaza."]],
  "115": ["Según Jones y Magarey, ¿qué no hay que hacer ante el paciente?",["Encerrarse en un pensamiento único","Formular preguntas abiertas","Aclarar formulando más preguntas"],["El curso recomienda no encerrarse en un pensamiento único, so pena de oír solo lo que se quiere oír.","Formular preguntas abiertas es al contrario recomendado por el curso.","El curso aconseja precisamente aclarar las cosas formulando más preguntas."]],
  "116": ["Entre las 7 categorías de hipótesis, ¿a qué corresponde la hipótesis de la limitación funcional?",["Al rol, a las actividades y a la participación del paciente","A los mecanismos de nocicepción y de inflamación","Al trabajo y al ocio que perpetúan el dolor"],["El curso asocia la hipótesis de limitación funcional al rol, a las actividades y a la participación (partes BIO y PSICO).","Eso corresponde a la hipótesis de los mecanismos patobiológicos.","Eso corresponde a la hipótesis de los factores contribuyentes."]],
  "117": ["Según el curso, ¿cómo debe anunciarse el pronóstico al paciente?",["Dando un plazo más bien largo, sin prometer una curación del 100 %","Prometiendo una curación completa para tranquilizarlo","Anunciando el plazo más corto posible"],["El curso aconseja dar un plazo más largo y no decir nunca al paciente que se le va a curar al 100 %.","El curso desaconseja prometer una curación del 100 %.","El curso recomienda al contrario dar un plazo más largo."]],
  "118": ["Según el curso, la metacognición corresponde al proceso mediante el cual el clínico:",["se autorregula para pensar sus propios pensamientos de forma reflexiva","percibe y analiza los datos recogidos","moviliza sus conocimientos biomédicos adquiridos"],["El curso define la metacognición como el proceso de autorregulación del clínico para elaborar sus pensamientos de manera escéptica y reflexiva (pensar sobre sus pensamientos).","Eso corresponde a la cognición, no a la metacognición.","Eso corresponde a la base de conocimientos, no a la metacognición."]],
  "119": ["Según el curso, ¿en qué se distingue el ejercicio terapéutico del ejercicio físico?",["Busca prevenir o tratar patologías dentro de un plan de rehabilitación","Busca únicamente mejorar la condición física general","Se dirige a toda persona que desee mejorar su bienestar"],["El curso opone el ejercicio terapéutico (prevenir o tratar patologías, necesidades individuales) al ejercicio físico, orientado a la condición o el bienestar.","Es la definición del ejercicio físico, destinado a cualquier persona que desee mejorar su forma, no del ejercicio terapéutico.","Ese público corresponde al ejercicio físico; el ejercicio terapéutico se dirige a personas con una patología bajo supervisión médica."]],
  "120": ["En cuanto al efecto del ejercicio terapéutico sobre el sistema cardiovascular a corto plazo, se observa:",["Un aumento de la frecuencia cardiaca y de la presión arterial","Una reducción de la frecuencia cardiaca basal","Un aumento de la capacidad aerobia desde el principio"],["A corto plazo, el ejercicio aumenta la frecuencia cardiaca y la presión arterial según la intensidad y los grupos musculares implicados.","Es un efecto a largo plazo, ligado a las adaptaciones del miocardio, no la respuesta aguda.","La mejora de la capacidad aerobia es una adaptación a largo plazo, no un efecto inmediato."]],
  "121": ["Según el curso, la hipoalgesia generalizada inducida por el ejercicio se obtiene sobre todo mediante:",["El ejercicio aerobio a intensidad media-alta","Un estiramiento estático prolongado del músculo doloroso","Un fortalecimiento isométrico localizado en la zona lesionada"],["El curso indica que el ejercicio aerobio, sobre todo a intensidad media-alta, induce una hipoalgesia generalizada a todo el cuerpo.","El estiramiento no es el mecanismo descrito; es el ejercicio aerobio el que produce la hipoalgesia generalizada.","El fortalecimiento local no se cita como fuente de la hipoalgesia generalizada descrita en el curso."]],
  "122": ["Según el curso, ¿qué principio resume la idea de que « la dosis es más importante que el tipo de ejercicio »?",["La dosificación adecuada prima sobre la elección del tipo de ejercicio","El tipo de ejercicio prima siempre sobre su dosificación","La duración total prima sobre la individualización del programa"],["El curso recoge explícitamente que la dosis es más importante que el tipo de ejercicio realizado.","Es lo contrario de lo que recoge el curso, que prioriza la dosis.","El curso insiste en la individualización y la dosis, no en la duración total como factor primero."]],
  "123": ["Según el curso, ¿cuál es el objetivo principal del masaje tonificante?",["Recuperar el tono, el volumen, la contractilidad y la fuerza","Facilitar la eliminación de los desechos del metabolismo muscular","Estimular los sistemas nervioso y circulatorio"],["El masaje tonificante busca la recuperación del tono, del volumen, de la contractilidad y de la fuerza, mediante maniobras profundas y prolongadas.","Es el objetivo del masaje de drenaje, con maniobras lentas y centrípetas.","Es el objetivo del masaje estimulante, mediante maniobras cortas, energéticas y rápidas."]],
  "124": ["Según el curso, ¿qué tipo de masaje desvía la sangre hacia la periferia provocando una fuerte hiperemia?",["El masaje revulsivo","El masaje sedante","El masaje de drenaje"],["El masaje revulsivo facilita la descongestión desviando la sangre hacia la periferia, lo que produce una fuerte hiperemia y una liberación de histamina.","El masaje sedante calma el dolor mediante maniobras lentas y superficiales; no provoca una hiperemia intensa.","El masaje de drenaje favorece la eliminación de los desechos mediante maniobras centrípetas, sin hiperemia revulsiva."]],
  "125": ["Según el curso, una contraindicación de la masoterapia es:",["Una inflamación o infección aguda","Una rigidez articular posinmovilización","Una contractura muscular crónica"],["El curso enumera la inflamación y la infección agudas entre las contraindicaciones del masaje.","La rigidez posinmovilización es más bien una indicación del masaje, no una contraindicación.","La contractura crónica no se enumera como contraindicación; lo son los estados agudos o infecciosos."]],
  "126": ["Según el curso, la movilización articular de grado IV de Maitland busca:",["Ganar los últimos grados de movilidad capsular al final del recorrido","Disminuir el dolor en los estados muy irritables","Aumentar la movilidad cuando predomina la rigidez, sin llegar al final del recorrido"],["El grado IV, de pequeña amplitud al final del recorrido, busca ganar los últimos grados de movilidad capsular.","Es el objetivo del grado I (pequeña amplitud, inicio del recorrido), no del grado IV.","Eso describe el grado III (gran amplitud hasta la barrera), no el grado IV al final del recorrido."]],
  "127": ["Según el curso, ¿cuál es el principio de la tracción articular?",["Liberar la presión intracapsular y limitar los roces entre superficies","Desplazar la articulación más allá de su amplitud a gran velocidad","Seguir el movimiento fisiológico para reducir la rigidez"],["La tracción libera la presión intracapsular y limita los roces articulares, lo que reduce el dolor percibido con el movimiento.","Eso describe la manipulación articular, no la tracción.","Eso corresponde a la movilización simple, no a la tracción, que libera la presión intracapsular."]],
  "128": ["Según el curso, en electroterapia las bajas frecuencias (inferiores a 50 Hz) se emplean para:",["La electroestimulación muscular","La analgesia por control de la compuerta","La penetración de los tejidos profundos"],["El curso indica que las bajas frecuencias (<50 Hz) sirven para la electroestimulación, y las altas frecuencias (>50 Hz) para la analgesia.","La analgesia se obtiene con las altas frecuencias (>50 Hz), no con las bajas.","Son las altas frecuencias las que favorecen la penetración profunda y la tolerancia a intensidades mayores."]],
  "129": ["Según el curso, el efecto del polo negativo (cátodo) de una corriente con efecto polar es:",["Una reacción alcalina con vasodilatación y excitación","Una reacción ácida con vasoconstricción y sedación","Una coagulación por liberación de oxígeno"],["El cátodo produce una reacción alcalina, libera hidrógeno y provoca vasodilatación, respuesta inflamatoria y excitación.","Es el efecto del polo positivo (ánodo): reacción ácida, coagulación, vasoconstricción y sedación.","La coagulación y la liberación de oxígeno son efectos del ánodo, no del cátodo."]],
  "130": ["Según el curso, la electrólisis percutánea (EPI) aplica una corriente galvánica con el fin de:",["Provocar una reacción inflamatoria controlada que estimule la reparación tisular","Producir una contracción muscular por despolarización de la motoneurona","Bloquear la conducción nerviosa mediante una corriente de alta frecuencia"],["La aplicación de la corriente galvánica a través de la aguja desencadena una inflamación controlada local que estimula la reparación de los tejidos.","Es el principio de la electroestimulación neuromuscular, no de la electrólisis percutánea.","La electrólisis emplea una corriente galvánica continua a 0 Hz, no un bloqueo nervioso de alta frecuencia."]],
  "131": ["Según el curso, en el músculo denervado la electroterapia actúa:",["Directamente sobre la fibra muscular","Despolarizando la motoneurona a través de la placa motora","Estimulando las fibras sensitivas A-beta"],["En el músculo denervado se estimula directamente la fibra muscular para mantener su metabolismo hasta la reinervación.","Eso atañe al músculo sano con inervación normal, en el que se activa el nervio a través de la placa motora.","La estimulación de las fibras A-beta corresponde al control del dolor, no a la contracción del músculo denervado."]],
  "132": ["Según el curso, ¿cuál es un efecto mecánico de la punción seca a nivel del punto gatillo?",["La eliminación de sustancias sensibilizantes como la sustancia P","La modulación de la actividad del asta dorsal de la médula","La activación de la ínsula y del córtex somatosensorial"],["Entre los efectos mecánicos, la punción seca elimina las sustancias sensibilizantes (sustancia P, bradicinina) y eleva el pH local.","Es un efecto neurofisiológico de la punción seca, no un efecto mecánico.","Esa activación cerebral corresponde a los efectos neurofisiológicos, no a los mecánicos."]],
  "133": ["Según el curso, el dolor de tipo inflamatorio se caracteriza por:",["Una mejoría con los antiinflamatorios y el frío","Una mejoría con el calor y un aumento en reposo","Un dolor muy localizado que disminuye en reposo"],["El dolor inflamatorio se acompaña de calor, enrojecimiento y edema, y mejora con antiinflamatorios y frío.","Ese perfil (aumenta en reposo, mejora con el calor) corresponde al dolor isquémico.","Son las características del dolor mecánico (ON/OFF, localizado, disminuye en reposo)."]],
  "134": ["Para que una disciplina se considere una ciencia, debe reunir:",["un corpus de conocimientos propio, un ámbito de actuación y un método sistemático","un corpus de conocimientos propio, un ámbito de actuación y una tradición reconocida","un ámbito de actuación, un método sistemático y un consenso entre expertos"],["El curso enuncia exactamente esas tres exigencias para que una disciplina acceda al estatuto de ciencia.","La tradición no figura entre las exigencias del curso: lo que se requiere es el método sistemático de acceso al saber.","El consenso de expertos no sustituye al corpus de conocimientos propio que exige el curso."]],
  "135": ["En la jerarquía de la evidencia presentada en el curso, ¿qué tipo de estudio se considera el patrón de referencia para determinar la eficacia de una intervención?",["El ensayo controlado aleatorizado, en el que los participantes se reparten al azar","El ensayo clínico controlado, cuyos grupos se constituyen sin sorteo","El estudio de cohortes, que sigue a un grupo de sujetos a lo largo del tiempo"],["El curso lo describe como un estudio experimental de alto nivel y como el patrón de referencia de la eficacia de una intervención.","Compara sí a los sujetos tratados y no tratados, pero la ausencia de aleatorización lo sitúa por debajo del ensayo aleatorizado.","Sigue los resultados según la exposición a un factor o a una intervención, pero se sitúa más abajo en la pirámide."]],
  "136": ["En el proceso de cinco etapas de la práctica basada en la evidencia, la etapa « Appraise » consiste en:",["transformar una necesidad de información en una pregunta que pueda responderse","evaluar de forma crítica la validez y la aplicabilidad de las pruebas encontradas","buscar en las bases de datos las mejores pruebas disponibles"],["Eso corresponde a la etapa « Ask », la primera del proceso, que precede a la búsqueda de las pruebas.","Es la etapa de evaluación crítica, que incluye la determinación del nivel de evidencia científica.","Eso corresponde a la etapa « Acquire », que aporta el material que la etapa siguiente evaluará."]],
  "137": ["En el método científico tal como se describe en el curso, la fase de análisis de los datos consiste en:",["determinar si la hipótesis es correcta, incorrecta o necesita ajustes","examinar los datos recogidos para ver si apoyan o rechazan la hipótesis","realizar la intervención y recoger las muestras de las variables estudiadas"],["Es la fase de las conclusiones, que viene después del análisis de los datos.","El curso define esa fase como el análisis de los datos recogidos para ver si apoyan o rechazan la hipótesis.","Es la fase de experimentación, que precede al análisis de los datos."]],
  "138": ["¿Qué efecto produce el ejercicio terapéutico sobre el metabolismo?",["Disminuye la masa muscular y ralentiza el gasto energético","Aumenta la masa grasa y rebaja el metabolismo basal","Mejora la sensibilidad a la insulina y ayuda a regular la glucemia"],["El ejercicio terapéutico aumenta la masa muscular, lo que mejora el metabolismo basal.","El curso describe lo contrario: pérdida de grasa corporal, ganancia de masa muscular y mejora del metabolismo basal.","El curso recoge ese efecto como beneficioso en personas diabéticas o con riesgo de diabetes."]],
  "139": ["Según el curso, la hipoalgesia inducida por el ejercicio aparece durante la sesión y puede persistir:",["hasta unas dos horas","hasta unas doce horas","hasta unos 30 minutos"],["No se enseña ninguna duración de ese orden: el efecto descrito se limita a unos treinta minutos.","Esa duración supera con mucho la ventana descrita en el curso, que es de unos 30 minutos.","El curso precisa que el efecto se produce durante la sesión de ejercicio y puede durar hasta 30 minutos."]],
  "140": ["¿Qué efecto produce el ejercicio terapéutico sobre el sistema respiratorio?",["Aumenta la capacidad pulmonar y facilita la eliminación del dióxido de carbono","Incrementa la retención de dióxido de carbono con un entrenamiento específico","Reduce la capacidad pulmonar mejorando a la vez la oxigenación de los tejidos"],["El curso recoge el aumento de la capacidad pulmonar, la mejora de la oxigenación y la eliminación del CO2.","El entrenamiento específico mejora la función de los músculos respiratorios y por tanto la eliminación del CO2.","La capacidad pulmonar aumenta con el ejercicio: el curso no describe ninguna reducción."]],
  "141": ["¿Qué se afirma de los efectos fisiológicos de la manipulación articular?",["Se conocen mal y no exigen la cavitación para producir analgesia","Se basan en la lubricación de las superficies por producción de líquido sinovial","Resultan de la liberación de la presión intracapsular de la articulación"],["El curso indica que los efectos no se conocen con precisión y que el fenómeno de cavitación no es necesario para la analgesia.","El curso atribuye ese efecto a la movilización articular analítica, no a la manipulación.","Es el principio de la tracción articular, descrita por separado en el curso."]],
  "142": ["Entre los efectos fisiológicos de la movilización articular analítica, se recoge:",["el aumento de la laxitud articular y la lubricación de las superficies articulares","la reabsorción del líquido intersticial y la activación del flujo de los linfangiones","la reducción de la excitabilidad neuromuscular y el descenso de la tasa de cortisol"],["El curso cita la activación del sistema Top-Down, la compuerta de control, el aumento de la laxitud y la producción de líquido sinovial.","Esos efectos de drenaje son los del drenaje linfático manual, no los de la movilización analítica.","Esos efectos figuran en el curso entre los del masaje clásico."]],
  "143": ["En una célula excitable, ¿qué caracteriza al potencial de acción frente al potencial graduado?",["Corresponde a la diferencia de carga entre el interior y el exterior en reposo","Su amplitud y su duración varían según la intensidad del estímulo aplicado","Responde a la ley del todo o nada y conserva siempre la misma intensidad"],["Es el potencial de reposo, situado normalmente entre -60 y -90 mV.","Es la definición del potencial graduado, que solo desencadena una respuesta si supera el umbral de excitación.","El curso precisa que, una vez desencadenado, el potencial de acción es un fenómeno « todo o nada », siempre de la misma intensidad."]],
  "144": ["Las corrientes interferenciales de Kotz (protocolo ruso) asocian dos frecuencias medias con el fin de obtener:",["una corriente unidireccional de 0 Hz con finalidad polar","una frecuencia de batido de 50 Hz con finalidad excitomotora","una frecuencia de batido de 100 Hz con finalidad analgésica"],["Una corriente continua de 0 Hz no se obtiene por interferencia de dos frecuencias medias.","El curso indica 2500 Hz + 2550 Hz, es decir una frecuencia de batido de 50 Hz, con finalidad excitomotora (protocolo ruso, reservado a los balances musculares más altos).","Es el resultado de las interferenciales de Nemec, que asocian 4000 Hz y 4100 Hz."]],
  "145": ["Según el curso, ¿cómo se aplica el TENS analgésico (100-150 Hz) según el tipo de dolor?",["En trenes en ambos casos, rebajando la frecuencia a 50 Hz","En modo continuo en los dolores crónicos y en trenes en los dolores agudos","En modo continuo en los dolores agudos y en trenes en los dolores crónicos"],["La frecuencia de 50 Hz corresponde al TENS excitomotor y no al TENS analgésico.","Las dos modalidades están invertidas respecto de lo que enseña el curso.","El curso asocia el modo continuo al dolor agudo y la aplicación en trenes (burst) al dolor crónico."]],
  "146": ["¿Cómo actúan las corrientes de alta frecuencia (más allá de 100 000 Hz)?",["Producen efectos polares con reacción ácida y reacción alcalina","No despolarizan la membrana nerviosa y actúan mediante producción de calor","Despolarizan las motoneuronas y provocan una contracción muscular"],["Los efectos polares exigen un flujo que circule en un solo sentido: corriente continua o corriente alterna asimétrica desequilibrada.","El curso indica que la alta frecuencia no despolariza la membrana y que los tejidos que se oponen a su paso se calientan.","Es el modo de acción de las bajas frecuencias empleadas en la electroestimulación del músculo inervado."]],
  "147": ["Según el curso, ¿por qué la intensidad aplicada en frecuencia media no debe superar los 20 mA?",["Porque más allá de ese umbral la membrana permanece en periodo refractario permanente","Porque cuanto más elevada es la corriente, más aumenta el calor desprendido, con riesgo de quemadura","Porque más allá de ese umbral la impedancia de la piel aumenta y bloquea la corriente"],["El periodo refractario depende de la frecuencia de los impulsos, no de la intensidad aplicada.","El curso recuerda la ley de Joule: más corriente significa más calor, de ahí el límite de 20 mA para evitar la quemadura.","El curso enseña lo contrario: la impedancia cutánea disminuye cuando la frecuencia aumenta."]],
  "148": ["Entre los objetivos de la fisioterapia respiratoria, se recoge:",["prevenir las disfunciones respiratorias y optimizar la función ventilatoria","corregir las deformidades torácicas y restaurar la movilidad articular costal","suprimir la producción de secreciones bronquiales y abolir la sensación de disnea"],["El curso fija como objetivos la prevención de las disfunciones, la optimización de la función pulmonar y ventilatoria y la mejora del aclaramiento mucociliar.","La corrección ortopédica no es un objetivo recogido por el curso, que apunta a la función ventilatoria y al drenaje.","El curso habla de mejorar el aclaramiento mucociliar y la sensación de disnea, no de suprimirlos."]],
  "149": ["¿Cuáles son los cuatro grandes grupos de técnicas de la fisioterapia respiratoria?",["Drenaje de las secreciones, aerosolterapia, oxigenoterapia y fortalecimiento muscular general","Drenaje de las secreciones, reeducación respiratoria, relajación respiratoria y fortalecimiento muscular","Reeducación respiratoria, relajación respiratoria, masaje torácico y ventilación mecánica"],["La aerosolterapia y la oxigenoterapia no figuran entre los grupos de técnicas enseñados.","Son las cuatro familias de técnicas presentadas en el curso.","El masaje torácico y la ventilación mecánica no forman parte de los cuatro grupos descritos."]],
  "150": ["¿De qué depende la elección de una técnica de fisioterapia respiratoria durante la evaluación del paciente?",["De la edad, de la cooperación y la tolerancia, de la gravedad y de la enfermedad","De la edad, del sexo, del índice de masa corporal y del nivel de actividad","De la gravedad, de la duración del ingreso, del tratamiento y del lugar de residencia"],["El curso recoge precisamente esos elementos de evaluación para orientar la elección técnica.","El sexo y el índice de masa corporal no figuran entre los criterios de evaluación enseñados.","Esos parámetros no son los que recoge el curso: insiste en la cooperación y la tolerancia del paciente."]],
  "151": ["¿Qué técnicas se emplean para la permeabilización de las vías respiratorias?",["Las técnicas manuales de bajo y de alto flujo, la presión espiratoria positiva y su variante oscilatoria","La presión espiratoria oscilatoria, la ventilación no invasiva y el entrenamiento de los músculos inspiratorios","Las técnicas manuales de bajo flujo, la aspiración traqueal y la humidificación de las vías aéreas"],["El curso enumera esas tres modalidades (técnicas manuales, PEP, PEP oscilatoria) en concepto de higiene bronquial.","La ventilación no invasiva y el entrenamiento inspiratorio corresponden a efectos distintos de la higiene bronquial.","La aspiración y la humidificación no figuran entre las técnicas de permeabilización citadas."]],
  "152": ["¿Por qué la fisioterapia respiratoria del lactante se orienta sobre todo al drenaje de las secreciones?",["Por la frecuencia de las deformidades ortopédicas del tórax a esa edad","Por las particularidades anatómicas y fisiológicas de su sistema respiratorio","Por la inmadurez aislada de sus músculos inspiratorios accesorios"],["Las deformidades ortopédicas atañen a los niños con una deficiencia neurológica grave.","El curso justifica la prioridad dada al drenaje por las particularidades fisiológicas y anatómicas del sistema respiratorio del lactante.","El curso no recoge ese motivo: invoca el conjunto de las particularidades anatómicas y fisiológicas."]],
  "153": ["En el niño con una deficiencia neurológica grave, la fisioterapia respiratoria se orienta a:",["la prevención de la obstrucción bronquial y la patología restrictiva ligada a las deformidades","la reeducación de la tos voluntaria y la relajación respiratoria torácica con prioridad","el fortalecimiento exclusivo de los músculos inspiratorios y la tolerancia al esfuerzo"],["El curso describe esa doble orientación en los niños con una afectación neurológica grave.","El curso destaca el manejo de la obstrucción bronquial y del componente restrictivo, no esos dos ejes.","El fortalecimiento muscular es un efecto esperado de la disciplina, pero no es la orientación descrita en esa población."]],
  "154": ["¿Qué efecto tiene la fisioterapia respiratoria sobre la capacidad funcional y la calidad de vida?",["Reduce la intensidad percibida de la disnea, pero disminuye la tolerancia al ejercicio","Aumenta la capacidad de ejercicio y reduce la intensidad percibida de la disnea","Aumenta la capacidad de ejercicio sin modificar la intensidad percibida de la disnea"],["La capacidad de ejercicio, al contrario, mejora según el curso.","El curso recoge la mejora de la capacidad de ejercicio, de la calidad de vida relacionada con la salud y el descenso de la disnea percibida.","La reducción de la intensidad percibida de la disnea forma parte de los efectos esperados."]],
  "155": ["Según el curso, entre los efectos fisiológicos de la fisioterapia respiratoria, ¿cuál cuenta con un nivel de evidencia A?",["El fortalecimiento de la musculatura respiratoria y de la musculatura general","La mejora del intercambio gaseoso con reducción de la hipercapnia","La mejora del aclaramiento mucociliar y de la permeabilización bronquial"],["El curso atribuye explícitamente un nivel de evidencia A al fortalecimiento muscular respiratorio y general.","Ese efecto está bien descrito, pero el curso no le asocia ningún nivel de evidencia A.","Ese efecto figura entre los de la disciplina, sin la mención del nivel de evidencia A."]],
  "156": ["¿Cómo define la Organización Mundial de la Salud la neurorrehabilitación?",["Un programa de mantenimiento que estabiliza las secuelas sin buscar una recuperación activa","Un proceso de compensación pasiva de los déficits mediante ayudas técnicas adaptadas","Un proceso activo que busca la mejor recuperación posible y la integración social"],["La definición busca explícitamente la mejor recuperación posible de la persona.","La definición recogida por el curso describe un proceso activo, no una compensación pasiva.","La definición citada insiste en el carácter activo del proceso, en la mejor recuperación posible y en la integración física, mental y social."]],
  "157": ["¿Qué estudia la neurofisioterapia como disciplina?",["Los mecanismos genéticos de la degeneración progresiva de las motoneuronas","Los efectos de una afectación del sistema nervioso sobre las funciones sensitivomotoras","Los efectos de los agentes físicos sobre la conducción nerviosa periférica"],["El curso no asigna ese objeto a la disciplina, que versa sobre las consecuencias sensitivomotoras de las afectaciones nerviosas.","El curso la define como el estudio de esos efectos, que repercuten en la funcionalidad y por tanto en la autonomía.","El estudio de los agentes físicos pertenece a otros ámbitos: la neurofisioterapia apunta a las funciones sensitivomotoras."]],
  "158": ["Tras su evaluación, ¿qué estrategia propone el neurofisioterapeuta?",["Evitar toda solicitación del sistema lesionado y compensar el déficit con ayudas técnicas","Estimular el sistema nervioso para crear nuevas conexiones y prevenir las complicaciones","Restablecer la conducción nerviosa estimulando eléctricamente los nervios periféricos"],["El curso propone al contrario estimular el sistema nervioso para aprovechar su plasticidad.","El curso describe herramientas que estimulan el sistema nervioso para generar nuevas conexiones, aumentar el potencial funcional y prevenir otras complicaciones.","No es la estrategia descrita: el objetivo es aumentar el potencial funcional mediante nuevas conexiones."]],
  "159": ["¿A qué tipo de modificación de la neuroplasticidad corresponden la formación de nuevas sinapsis y la regeneración axonal?",["A las modificaciones neuroquímicas","A las modificaciones morfológicas","A las modificaciones fisiológicas"],["El nivel neuroquímico corresponde a los cambios de los neurotransmisores y de sus receptores.","El curso clasifica las nuevas sinapsis y la regeneración axonal entre los cambios morfológicos.","El nivel fisiológico corresponde a las variaciones de la eficacia sináptica."]],
  "160": ["¿Qué designa el feed-back en el control del movimiento?",["Las instrucciones verbales dadas al paciente antes de iniciar el movimiento","Las informaciones sensoriales recibidas durante la ejecución del movimiento o de la postura","Las informaciones almacenadas y empleadas antes de la ejecución de un movimiento futuro"],["El feed-back designa informaciones sensoriales internas, no las instrucciones del terapeuta.","El curso define el feed-back como el conjunto de las informaciones sensoriales recibidas durante la ejecución.","Es la definición del feed-forward, construido a partir de las informaciones de feed-back."]],
  "161": ["¿Cómo se constituye el feed-forward?",["Mediante el almacenamiento de las informaciones sensoriales recibidas en las ejecuciones anteriores","Mediante la corrección continua del movimiento a medida que se ejecuta","Mediante la sola maduración de las vías motoras descendentes durante el desarrollo"],["El curso indica que las informaciones del feed-back se integran y se almacenan para formar el feed-forward, empleado antes de la ejecución futura.","La corrección durante la ejecución se basa en el feed-back: el feed-forward precede al movimiento.","El curso vincula el feed-forward a la experiencia sensorial almacenada, no a la sola maduración."]],
  "162": ["¿Cuáles son los tres procesos pertinentes de la neuroplasticidad?",["El aprendizaje motor, la plasticidad poslesional y la regulación autónoma del tono","La neuroplasticidad durante el desarrollo, el envejecimiento cerebral y la memoria declarativa","La neuroplasticidad durante el desarrollo, el aprendizaje motor y la plasticidad poslesional"],["La regulación autónoma del tono no forma parte de los tres procesos enumerados.","El envejecimiento y la memoria declarativa no figuran entre los procesos recogidos.","El curso recoge esos tres procesos como pertinentes en fisioterapia neurológica."]],
  "163": ["¿A qué alteración se vincula la enfermedad de Parkinson en el paciente neurológico?",["A una alteración genómica","A una lesión de la médula espinal","A una perturbación dopaminérgica"],["La alteración genómica se menciona por separado y no corresponde a la enfermedad de Parkinson.","La lesión medular se cita como una entidad distinta en el curso.","El curso asocia la enfermedad de Parkinson a una perturbación dopaminérgica."]],
  "164": ["¿Cuáles son las características de la corriente galvánica empleada en electrólisis percutánea?",["Una corriente alterna simétrica de baja frecuencia, ajustada entre 0,5 y 10 mA","Una corriente continua unidireccional, de frecuencia nula, ajustada entre 15 y 20 mA","Una corriente continua unidireccional, de frecuencia nula, ajustada entre 0,5 y 10 mA"],["La corriente galvánica no es alterna: circula en un solo sentido entre ánodo y cátodo.","El tipo de corriente es correcto, pero la intensidad enseñada se sitúa entre 0,5 y 10 mA; 15 a 20 mA no es el rango clínico del curso.","El curso describe una corriente continua unidireccional de intensidad constante, de 0 Hz, ajustada típicamente entre 0,5 y 10 mA."]],
  "165": ["¿En qué consiste el efecto mecánico de la electrólisis percutánea?",["En una elevación del pH por eliminación local de las sustancias sensibilizantes del músculo","En una mecanotransducción por activación de los fibrocitos, ligada al movimiento de la aguja","En una rotura y después una regeneración de las fibras musculares y de las placas motoras"],["La elevación del pH y la eliminación de las sustancias sensibilizantes corresponden a los efectos mecánicos de la punción seca.","El curso vincula el efecto mecánico al movimiento de la aguja, que activa los fibrocitos y produce una mecanotransducción.","Ese efecto mecánico se describe para la punción seca a nivel del punto gatillo."]],
  "166": ["¿En qué consiste la neuromodulación percutánea?",["En una aguja conectada a una corriente de baja frecuencia, aplicada al nervio periférico bajo ecografía","En una aguja introducida sin corriente en el punto gatillo muscular, sin inyección de sustancia","En una aguja conectada a una corriente galvánica aplicada al tendón degenerado bajo control ecográfico"],["El curso la define como un abordaje invasivo e indoloro dirigido al epineuro del nervio periférico con una corriente de baja frecuencia, bajo ecografía.","Es la definición de la punción seca, técnica distinta de la neuromodulación.","Esa descripción corresponde a la electrólisis percutánea, que apunta al foco lesional del tendón."]],
  "167": ["¿A qué corresponde el mecanismo de inhibición medular de la neuromodulación percutánea?",["A la activación de las estructuras analgésicas cerebrales que liberan endorfinas y serotonina","A la normalización del umbral de activación de los nociceptores irritados o hiperactivos","Al bloqueo de las señales dolorosas en la médula por las interneuronas inhibidoras"],["Eso corresponde a la modulación descendente, cuyo resultado clínico es una analgesia prolongada.","Eso corresponde a la desensibilización periférica, que disminuye el dolor local.","El curso vincula ese mecanismo a las interneuronas inhibidoras del asta dorsal y a la teoría del control de la compuerta, con reducción inmediata del dolor."]],
  "168": ["¿Cuál es el objetivo de la técnica de entrada y salida rápida de Hong en punción seca profunda?",["Obtener una analgesia inmediata evitando toda respuesta de espasmo local","Estirar el citoesqueleto mediante rotación mantenida de la aguja en el punto gatillo","Reproducir el dolor del paciente y generar respuestas de espasmo local"],["Las respuestas de espasmo local son al contrario buscadas con esa técnica.","La rotación de la aguja corresponde a la modalidad de torsión, distinta de la entrada-salida rápida.","El curso presenta esa modalidad, la más empleada en clínica, como destinada a reproducir el dolor y a obtener respuestas de espasmo local."]],
  "169": ["Según el curso, ¿cuáles son los parámetros de la punción seca superficial?",["Una introducción de 5 a 10 mm, mantenida unos 10 a 15 minutos","Una introducción de 5 a 10 mm, mantenida unos 30 segundos a 3 minutos","Una introducción de 20 a 30 mm, mantenida unos 30 segundos a 3 minutos"],["La duración es errónea: el curso recoge una aplicación de unos 30 segundos a 3 minutos.","Son los parámetros enseñados para la punción seca superficial, a la que puede añadirse una corriente o una rotación.","Esa profundidad corresponde a una punción profunda, no a la modalidad superficial."]],
  "170": ["Según el curso, ¿qué características distinguen a los nociceptores de tipo C?",["Una conducción lenta, de unos 20 m/s, y un carácter mecanotérmico","Una conducción muy lenta, de unos 2 m/s, y un carácter polimodal","Una conducción rápida, de gran diámetro, sensible al tacto y a la presión"],["Esas características son las de los nociceptores A-delta, mecanosensibles y mecanotérmicos.","El curso describe las fibras C como muy lentas (2 m/s) y polimodales, que responden a estímulos térmicos, mecánicos y químicos.","Eso corresponde a las fibras A-beta del tacto y de la presión, que no son nociceptores."]],
  "171": ["¿Dónde transmite el nociceptor de primer orden la información al nociceptor de segundo orden?",["En el córtex prefrontal y el sistema límbico","En el tálamo, antes del relevo cortical","En el asta dorsal de la médula espinal"],["Esas estructuras se alcanzan en último lugar, tras el relevo talámico, y no a la salida del nociceptor de primer orden.","El tálamo es el relevo siguiente, alcanzado por el nociceptor de segundo orden si el estímulo es suficiente.","El curso sitúa ese relevo en el asta dorsal, donde el nociceptor de primer orden transmite al de segundo orden."]],
  "172": ["¿En qué consiste el sistema Top-Down de regulación del dolor?",["Células del tronco cerebral inhiben o aumentan el paso de la información nociva","Receptores membranarios elevan su umbral de activación a nivel periférico","Fibras de gran diámetro cierran el acceso de la interneurona medular al dolor"],["El curso describe células ON-OFF del tronco cerebral que actúan entre los nociceptores de primer y de segundo orden.","El umbral elevado de los receptores caracteriza al propio nociceptor; no se trata de una regulación descendente.","Es la teoría de la compuerta, mecanismo distinto del sistema Top-Down."]],
  "173": ["Según la clasificación del curso en función de la duración, el dolor subagudo corresponde a:",["un dolor que evoluciona entre cuatro días y tres meses","un dolor que evoluciona desde más de tres meses","un dolor que evoluciona desde menos de tres días"],["El curso sitúa el dolor subagudo entre 4 días y 3 meses de evolución.","Ese plazo define el dolor crónico, asimilado a un retraso de la reparación tisular.","Esa duración define el dolor agudo en la clasificación del curso."]],
  "174": ["Según el curso, ¿cómo se comporta un dolor de origen isquémico?",["Aumenta por la noche y se acompaña de hormigueos y de pérdida de fuerza","Aumenta en reposo, disminuye con el movimiento y mejora con el calor","Aumenta con el movimiento, disminuye en reposo y mejora con el frío"],["Esos signos neurológicos caracterizan el dolor neuropático, ligado a una lesión del nervio.","El curso vincula el dolor isquémico a una disminución del flujo sanguíneo, que empeora en reposo y mejora con el calor.","Ese perfil mezcla dos cuadros del curso: el dolor mecánico, muy localizado y que disminuye en reposo, y el dolor inflamatorio, que mejora con el frío y los antiinflamatorios."]],
  "175": ["¿En qué tejidos puede aparecer la respuesta inflamatoria?",["En todos los tejidos, vascularizados o no","Únicamente en los epitelios y las mucosas","Únicamente en los tejidos conjuntivos vascularizados"],["La ausencia de vascularización impide la respuesta inflamatoria tal como se describe en el curso.","El curso no limita la inflamación a esos tejidos: exige un tejido conjuntivo vascularizado.","El curso precisa que la respuesta inflamatoria solo aparece en los tejidos conjuntivos vascularizados."]],
  "176": ["¿Qué cambio sigue inmediatamente a la agresión tisular en la secuencia inflamatoria?",["Cambios metabólicos con hipoxia","Cambios hemodinámicos locales","Una migración de los leucocitos hacia el foco"],["El curso sitúa los cambios metabólicos, con hipoxia, justo después de la agresión y antes de la activación de los mediadores.","Sobrevienen más tarde, tras la activación de los mediadores inflamatorios.","La migración leucocitaria es la última etapa de la secuencia descrita."]],
  "177": ["¿Cómo termina una inflamación aguda?",["El líquido acumulado se drena por el sistema linfático y las células inflamatorias entran en apoptosis","El líquido persiste y las células inflamatorias se mantienen con periodos de intensidad variable","El líquido acumulado se reabsorbe por los capilares venosos y las células inflamatorias se fibrosan"],["El curso describe el drenaje linfático del líquido y de las proteínas y después la apoptosis de las células inflamatorias, lo que normaliza el tejido.","Esa evolución caracteriza la inflamación crónica, que dura de 3 a 6 meses o incluso años.","El curso atribuye el drenaje al sistema linfático y describe una muerte celular programada, no una fibrosis."]],
  "178": ["¿Cómo define el curso el ejercicio terapéutico?",["Una ejecución sistemática y planificada de movimientos, posturas y actividades físicas con objetivos precisos","Una sucesión de movimientos libres elegidos espontáneamente por el paciente según sus sensaciones del día","Un conjunto de posturas mantenidas pasivamente por el terapeuta sin participación activa del paciente"],["El curso retoma esa definición: una ejecución sistemática y planificada, concebida para corregir o prevenir los trastornos físicos y restaurar las funciones.","El carácter sistemático y planificado es constitutivo del ejercicio terapéutico: nada queda en él a la elección espontánea.","La definición versa sobre movimientos, posturas y actividades físicas ejecutados por el paciente, y no sobre una colocación pasiva."]],
  "179": ["Un programa de cribado destinado a reducir la gravedad y la duración de una enfermedad ya instaurada, así como sus secuelas, corresponde a:",["La prevención secundaria","La prevención primaria","La prevención terciaria"],["El curso define ese nivel por el diagnóstico precoz y la reducción de la gravedad, de la duración y de las secuelas de la enfermedad existente.","Interviene antes de la aparición de la enfermedad, mediante actividades de promoción de la salud en las poblaciones de riesgo.","Recurre a las técnicas de rehabilitación para reducir el grado o limitar la progresión de la discapacidad actual en personas con una enfermedad crónica e irreversible."]],
  "180": ["En la síntesis sobre las lesiones de los isquiotibiales, ¿qué tipo de trabajo muscular acorta más el plazo de retorno al deporte?",["Un trabajo excéntrico que insiste en el alargamiento muscular","Un trabajo concéntrico de fortalecimiento progresivo del músculo","Un trabajo isométrico mantenido en recorrido interno del músculo"],["Los dos estudios citados muestran que los ejercicios excéntricos en alargamiento (protocolo L) reducen entre un 38 y un 45 % el tiempo necesario para volver al deporte, en comparación con un fortalecimiento concéntrico.","Es el protocolo de comparación, frente al cual el trabajo en alargamiento se mostró superior en el plazo de retorno al deporte.","Ese modo de contracción no es el que evalúan los estudios citados, que oponen trabajo en alargamiento y trabajo concéntrico."]],
  "181": ["Según la conclusión del curso, ¿en qué horquilla se sitúa el tiempo de retorno al deporte tras una lesión muscular?",["Entre 15 y 86 días","Entre 2 y 15 días","Entre 90 y 180 días"],["La conclusión recoge esa horquilla muy amplia, junto con tasas de recidiva que van del 0 al 70 %.","El curso sitúa el límite superior en 86 días: una horquilla que se detiene en 15 días recoge solo el plazo más corto observado.","Esa duración supera el límite superior recogido por el curso, fijado en 86 días."]],
  "182": ["Comenzar la rehabilitación dos días después de la lesión muscular en lugar de nueve días:",["Adelanta unos veinte días el retorno al deporte","No tiene ninguna incidencia en el plazo de retorno al deporte","Retrasa el retorno al deporte al prolongar la cicatrización"],["El curso opone un retorno a los 63 días con la rehabilitación precoz frente a 83 días con la rehabilitación diferida.","Las cifras recogidas muestran al contrario una diferencia clara entre la atención precoz y la diferida.","El curso atribuye a la rehabilitación precoz un retorno más rápido, y no una prolongación del plazo."]],
  "183": ["¿Qué persiste mucho tiempo después de una lesión muscular y puede aumentar el riesgo de recidiva?",["Cambios estructurales en los tejidos afectados","Una inflamación aguda mantenida en el músculo lesionado","Una pérdida definitiva del reclutamiento nervioso del músculo"],["El curso subraya que esas modificaciones estructurales persisten mucho después de la lesión e influyen en la función muscular.","No se describe ninguna inflamación prolongada: lo que permanece son remodelaciones del tejido.","El curso no describe ninguna afectación nerviosa definitiva tras una lesión muscular."]],
  "184": ["¿Qué designa la « función muscular » cuyo nivel mejora el ejercicio terapéutico?",["La capacidad del músculo de producir tensión y de funcionar","La capacidad del músculo de alargarse sin dolor en reposo","La capacidad del músculo de almacenar glucógeno durante el esfuerzo"],["El curso define explícitamente la mejora de la función muscular como la de la capacidad del músculo de producir tensión.","El alargamiento corresponde a la flexibilidad y a la elasticidad musculotendinosas, y no a la definición recogida aquí.","Las reservas energéticas corresponden a los cambios metabólicos, descritos aparte de las cualidades musculares."]],
  "185": ["¿Mediante qué mecanismos aumenta el ejercicio terapéutico la resistencia a la fatiga muscular?",["Mediante la hipertrofia muscular y un mejor reclutamiento de las fibras durante el esfuerzo","Mediante el aumento de la amplitud articular y de la elasticidad de los tendones","Mediante la disminución del número de unidades motoras solicitadas durante la actividad"],["El curso relaciona directamente la ganancia de resistencia a la fatiga con la hipertrofia y el reclutamiento de las fibras durante la actividad.","Esas ganancias corresponden a la movilidad y a la flexibilidad, que constituyen un efecto distinto de la resistencia a la fatiga.","El curso describe una ganancia de eficiencia en el esfuerzo, no una reducción de las unidades motoras puestas en juego."]],
  "186": ["¿Cómo favorece la mayor vascularización inducida por el ejercicio la reparación de los tejidos?",["Aporta nutrientes y sustancias tróficas y elimina los desechos","Aumenta la presión intramuscular y comprime la zona lesionada","Rebaja la temperatura local y ralentiza el metabolismo tisular"],["El curso describe un aporte de nutrientes y de sustancias tróficas indispensables para la regeneración, con evacuación de los desechos.","No se describe ninguna compresión de la lesión: es el aporte circulatorio el que sostiene la regeneración.","Un enlentecimiento metabólico iría contra la regeneración, que exige al contrario aportes sostenidos."]],
  "187": ["¿Qué abarca precisamente el aumento de la capacidad aerobia obtenido con el ejercicio terapéutico?",["Una mejor utilización del oxígeno y una mayor eficiencia cardiovascular","Un mayor almacenamiento de oxígeno en los músculos durante las fases de reposo","Una elevación del metabolismo basal ligada a la modificación de la composición corporal"],["El curso define esa capacidad como la aptitud del cuerpo para utilizar el oxígeno, con ganancia de resistencia y de eficiencia del sistema cardiovascular.","Se trata de una mejor utilización del oxígeno durante el esfuerzo, y no de una reserva muscular en reposo.","Ese efecto pertenece a los cambios metabólicos, que forman un capítulo distinto de las adaptaciones cardiovasculares."]],
  "188": ["Sobre el sistema neuromuscular, la mejora de la coordinación y del control del movimiento se explica por:",["La mejora de las conexiones neuromusculares","El alargamiento del tiempo de contracción de las fibras","El aumento del número de fibras musculares"],["El curso atribuye la optimización de la coordinación y del control motor a la mejora de las conexiones entre nervio y músculo.","El curso no describe ninguna modificación de la velocidad de contracción: vincula el control del movimiento a la calidad del mando nervioso.","No se describe ninguna creación de fibras nuevas; es el enlace entre el nervio y el músculo lo que el ejercicio optimiza."]],
  "189": ["¿Qué efecto produce el ejercicio terapéutico sobre el sistema inmunitario?",["Aumenta la producción de células que combaten la infección y regulan la inflamación","Deprime transitoriamente las defensas del organismo en favor de la reparación tisular","Incrementa sobre todo la producción de glóbulos rojos y el transporte de oxígeno"],["El curso recoge un aumento de la actividad inmunitaria, con producción de células de defensa y regulación de la inflamación.","No se describe ninguna depresión inmunitaria: la actividad inmunitaria se refuerza al contrario.","El efecto descrito atañe a las células de la inmunidad, no a la serie eritrocitaria ni al transporte de oxígeno."]],
  "190": ["¿Qué efectos psicológicos atribuye el curso al ejercicio terapéutico?",["Una reducción del estrés y de la ansiedad y una mejora del estado de ánimo","Una reducción de la ansiedad a costa de un estado de ánimo más fluctuante","Una mejora del estado de ánimo sin efecto medible sobre la ansiedad"],["El curso recoge esos dos efectos psicológicos: el descenso del estrés y de la ansiedad, y la mejora del estado de ánimo.","El curso no describe ninguna contrapartida en el estado de ánimo, que presenta al contrario como mejorado.","La reducción del estrés y de la ansiedad figura explícitamente entre los efectos psicológicos recogidos."]],
  "191": ["¿Por qué recomienda el curso vincular los objetivos de ejercicio a actividades que tengan importancia para el paciente?",["Porque eso aumenta su motivación para realizar el programa","Porque eso dispensa de fijar objetivos medibles","Porque eso permite aumentar la carga sin supervisión"],["El curso exige objetivos claros y alcanzables, ligados a actividades significativas, precisamente para aumentar la motivación.","El carácter claro y alcanzable del objetivo sigue exigiéndose, cualquiera que sea la actividad elegida como referencia.","La elección de actividades significativas atañe a la finalidad del ejercicio, no al ajuste de la carga."]],
  "192": ["¿Cómo debe presentar el fisioterapeuta un nuevo ejercicio al paciente?",["Demostrándolo con dominio y verbalizándolo, para que el paciente lo imite","Describiéndolo únicamente por escrito en una ficha detallada entregada al paciente","Dejando que el paciente lo pruebe solo antes de toda explicación del gesto"],["El curso describe una demostración dominada, precisa y verbalizada, que el paciente observa primero y después reproduce.","El curso exige una demostración realizada ante el paciente, que un documento escrito no puede sustituir.","El orden recogido sitúa la intervención del profesional antes de la primera ejecución del paciente."]],
  "193": ["¿Qué cualidades debe reunir el retorno dado al paciente (feedback)?",["Ser inmediato y positivo, para motivar sin desmoralizar","Ser diferido al final de la sesión para no interrumpir el ejercicio","Ser estrictamente correctivo para evitar todo exceso de confianza"],["El curso exige un feedback inmediato y positivo, que motive sin desmoralizar y consolide los resultados obtenidos.","El curso reclama un retorno inmediato, dado en el momento en que se realiza el gesto.","Un retorno únicamente correctivo desmoraliza al paciente, mientras que su dimensión positiva se exige explícitamente."]],
  "194": ["¿Qué debe hacer el fisioterapeuta mientras el paciente realiza sus ejercicios?",["Observar atentamente, detectar los errores y reforzar el gesto correcto","Dejar que el paciente termine sin intervenir, para preservar su autonomía","Contar las repeticiones sin comentar la calidad del gesto realizado"],["El curso impone la observación atenta, la detección de los errores, la intervención si es necesario y el refuerzo verbal o físico del gesto correcto.","La ausencia de intervención deja que se instalen los errores: el curso exige corregir durante la práctica.","El recuento no basta: lo que debe vigilarse y comentarse es la calidad del movimiento."]],
  "195": ["¿Qué significa favorecer la autonomía del paciente en el ejercicio terapéutico?",["Que realice el ejercicio solo, comprenda su finalidad y lo integre en su vida diaria","Que elija él mismo los ejercicios que considera útiles para su patología","Que prosiga su rehabilitación sin ninguna reevaluación posterior"],["El curso espera una ejecución autónoma y comprendida, y después su integración en la vida diaria en forma de rutina.","La elección de los ejercicios sigue siendo una decisión profesional: la autonomía atañe a la ejecución y a la comprensión.","La autonomía de ejecución no suprime ni el seguimiento ni la reevaluación del paciente por el profesional."]],
  "196": ["Según la revisión citada en el curso, ¿qué dosis semanal de ejercicio es necesaria para reducir moderadamente los síntomas depresivos del posparto?",["Al menos 350 MET-min por semana, es decir unos 80 minutos de intensidad moderada","Al menos 150 MET-min por semana, es decir unos 30 minutos de intensidad moderada","Al menos 700 MET-min por semana, es decir unos 160 minutos de intensidad moderada"],["El metaanálisis citado fija ese umbral de unos 350 MET-min semanales para obtener una reducción moderada de los síntomas.","Esa dosis queda por debajo del umbral recogido por la revisión para obtener una reducción moderada.","Esa dosis supera con mucho el umbral descrito como necesario para una reducción moderada de los síntomas."]],
  "197": ["Según el metaanálisis citado, ¿en cuánto reduce el ejercicio el riesgo de depresión posparto?",["En un 45 % aproximadamente","En un 10 % aproximadamente","En un 80 % aproximadamente"],["La revisión recoge una disminución del riesgo de depresión posparto del 45 %, que corresponde a una odds ratio de 0,55.","Esa reducción es claramente inferior al efecto recogido por la revisión citada en el curso.","Una magnitud así supera con mucho el efecto recogido para el ejercicio en el posparto."]],
  "198": ["¿Qué es un objetivo terapéutico, tal como lo define el curso?",["Una meta específica y medible que guía la planificación del tratamiento","Un pronóstico de recuperación establecido desde el primer día de la atención","Una técnica elegida por el fisioterapeuta según su ámbito de especialización"],["El curso lo concibe como una meta específica y medible, que sirve de guía para planificar y después evaluar las intervenciones terapéuticas.","El pronóstico estima una evolución probable, mientras que el objetivo fija un resultado que alcanzar y medir.","La técnica es un medio de intervención: sirve al objetivo pero no constituye la meta perseguida."]],
  "199": ["Según los estatutos profesionales citados en el curso, ¿qué etapa precede obligatoriamente a todo acto fisioterápico?",["La determinación del balance y del diagnóstico fisioterápico","La obtención de una prescripción del médico rehabilitador","La inscripción del paciente en el registro de las profesiones sanitarias"],["El curso hace del balance y del diagnóstico fisioterápico la etapa previa a todo acto de la profesión.","Los estatutos citados sitúan antes del acto el balance y el diagnóstico fisioterápicos, y no la obtención de una prescripción.","Ese registro recoge a los propios profesionales y no constituye en absoluto una etapa del tratamiento."]],
  "200": ["En la CIF, ¿qué abarca el término genérico « funcionamiento »?",["Las funciones y estructuras corporales, las actividades y la participación","Únicamente las funciones corporales que aún se conservan a pesar de la enfermedad","Los factores ambientales y personales del entorno de vida del paciente"],["El curso define el funcionamiento como el término genérico que engloba las funciones y las estructuras corporales, las actividades y la participación.","El término es mucho más amplio y no se reduce al componente de las funciones corporales.","Esos elementos componen los factores contextuales, que forman la otra parte de la clasificación."]],
  "201": ["Según el curso, ¿de qué resulta la discapacidad de una persona?",["De una interacción compleja entre el estado de salud, los factores personales y el entorno de vida","De la sola gravedad de la lesión orgánica constituida inicialmente por la enfermedad","De la etiología de la enfermedad, tal como la OMS la codifica en su clasificación"],["El curso describe la discapacidad como el producto de una interacción compleja entre el estado de salud, los factores personales y las circunstancias externas de vida.","Reducir la discapacidad a la lesión reproduce el modelo lineal anterior, que la CIF ha superado precisamente.","La clasificación por etiología corresponde a otra clasificación de la OMS, ajena al enfoque de la discapacidad recogido aquí."]],
  "202": ["En la CIF, ¿qué describe el « desempeño » o realización, por oposición a la capacidad?",["Lo que la persona hace en su entorno actual","La aptitud de la persona para llevar a cabo una tarea o una acción","El grado de autonomía que se espera de una persona de esa edad"],["El curso lo define por el contexto: es « el acto de involucrarse en una situación actual », es decir en el entorno de vida real.","Es la definición de la capacidad, que se aprecia independientemente del contexto de vida real.","La CIF describe lo que la persona hace, sin establecer una norma esperada según características individuales."]],
  "203": ["¿A qué componente de la CIF pertenecen la edad, el nivel educativo y los hábitos de vida de un paciente?",["A los factores personales","A los factores ambientales","A las funciones corporales"],["El curso incluye en ellos el sexo, la edad, la educación, la profesión y los modos de vida, que forman el contexto particular de la vida del individuo.","Estos describen el medio físico y social exterior: domicilio, trabajo, servicios, reglamentaciones y actitudes.","El enunciado no versa sobre el funcionamiento del organismo, sino sobre el contexto particular de la vida de la persona."]],
  "204": ["En la CIF, ¿dónde se clasifican las funciones mentales o psicológicas?",["Entre las funciones corporales","Entre las estructuras corporales","Entre las actividades y la participación"],["El curso precisa que el término « cuerpo » designa el organismo entero, cerebro incluido: las funciones mentales se incluyen por tanto en él.","Las estructuras corporales designan las partes anatómicas del organismo —el estudio de caso codifica así la articulación de la rodilla—, y no las funciones en sí.","Ese componente describe la ejecución de tareas y la implicación en situaciones vitales, no las funciones del organismo."]],
  "205": ["El curso indica que una deficiencia puede provocar otra. ¿Qué ejemplo da de ello?",["Una disminución de la fuerza muscular puede alterar las funciones de movimiento","Una limitación de la actividad conlleva siempre una restricción de la participación","Una enfermedad crónica produce necesariamente una deficiencia duradera"],["El curso cita precisamente ese encadenamiento, igual que cita un déficit respiratorio que repercute en el funcionamiento cardiaco.","Esas dos nociones pertenecen a la vertiente negativa del funcionamiento, pero no ilustran una deficiencia que produzca otra.","La noción de deficiencia es más amplia que la de enfermedad y no se deriva de ella automáticamente."]],
  "206": ["¿Qué principios recoge el curso como base de la ética profesional en fisioterapia?",["Beneficencia, no maleficencia, autonomía y justicia","Beneficencia, confidencialidad, autonomía y eficiencia","No maleficencia, justicia, solidaridad y responsabilidad"],["El curso presenta esos cuatro principios como la base de la ética profesional del fisioterapeuta.","La confidencialidad y la eficiencia son exigencias de la práctica, no los cuatro principios éticos enunciados.","La solidaridad y la responsabilidad no figuran entre los cuatro principios recogidos por el curso."]],
  "207": ["¿En qué debe basarse la relación con el paciente, según el código deontológico citado en el curso?",["En el respeto, la confianza y la comprensión mutua","En la autoridad del profesional y la observancia estricta del paciente","En la sola prescripción establecida por el médico de cabecera"],["El código citado fundamenta la relación en esas tres exigencias, completadas con la información al paciente y su consentimiento informado.","El paciente conserva el derecho a ser informado de su tratamiento y a elegir o cambiar de fisioterapeuta.","La relación se establece directamente entre el fisioterapeuta y su paciente y no se reduce a una prescripción."]],
  "208": ["¿Cómo se sitúa la masoterapia desde el punto de vista de la aceptación por los pacientes y del nivel de evidencia científica?",["Aceptación alta de los pacientes, nivel de evidencia bajo","Aceptación baja de los pacientes, nivel de evidencia alto","Aceptación alta de los pacientes, nivel de evidencia alto"],["El curso subraya ese desfase: los pacientes se adhieren muy bien a la masoterapia mientras que los trabajos que la respaldan son de baja calidad metodológica.","La aceptación por los pacientes se describe al contrario como alta, y las pruebas disponibles siguen siendo limitadas.","La aceptación es alta, pero el nivel de evidencia se califica de bajo por la escasa calidad metodológica de los estudios."]],
  "209": ["¿Qué maniobra de masaje pertenece al grupo de las maniobras básicas?",["El amasamiento","El roce superficial","La percusión"],["El amasamiento figura entre las maniobras básicas, junto con la fricción profunda y las presiones.","El roce superficial, como la fricción superficial, es una maniobra preparatoria que abre la sesión.","La percusión pertenece a las maniobras complementarias, con la vibración, las sacudidas y el pinzamiento."]],
  "210": ["¿Qué efecto figura entre los efectos generales del masaje clásico?",["Un aumento de la temperatura muscular","Un aumento de la tasa de cortisol en sangre","Una disminución del flujo sanguíneo de la región tratada"],["La elevación de la temperatura del músculo se cita entre los efectos generales del masaje clásico, con la relajación y la reducción de las adherencias entre los tejidos.","El masaje clásico se acompaña de relajación y de un descenso de la tasa de cortisol, no de un aumento.","El masaje clásico aumenta el flujo sanguíneo de la región tratada en lugar de reducirlo."]],
  "211": ["A nivel de la piel, ¿mediante qué mecanismo favorece el masaje la eliminación de los desechos?",["Mediante un aumento de la sudoración","Mediante una aceleración de la renovación de la capa córnea","Mediante una vasoconstricción de la zona tratada"],["Entre los efectos cutáneos, el curso recoge una eliminación de los desechos obtenida gracias al aumento de la sudoración.","No se describe ningún efecto sobre la renovación de la capa córnea: la piel se beneficia sobre todo de una mejora de su trofismo.","La respuesta cutánea al masaje es una vasodilatación activa con hiperemia local, y no una vasoconstricción."]],
  "212": ["¿Qué efecto ejerce el masaje sobre el tejido celular subcutáneo?",["La reabsorción de los adipocitos por lisis mecánica","La neoformación de fibras elásticas en la dermis","El aumento de la viscosidad del líquido intersticial"],["A nivel subcutáneo, la presión de las maniobras produce una lisis mecánica que permite la reabsorción de los adipocitos.","No se describe ninguna neoformación de fibras: los efectos subcutáneos son circulatorios y atañen a los líquidos y a los adipocitos.","Los líquidos de edema y de derrame se reabsorben; su viscosidad no es el elemento que el masaje modifica."]],
  "213": ["¿De qué depende que el masaje relaje el músculo o, al contrario, aumente su excitabilidad?",["De los parámetros de aplicación elegidos","De la temperatura inicial del músculo","Del número de sesiones ya realizadas"],["La relajación o la excitabilidad muscular obtenida depende de los parámetros de aplicación elegidos para la maniobra.","La temperatura del músculo antes de la sesión no es el criterio recogido: el efecto obtenido depende de cómo se aplique la maniobra.","La acumulación de sesiones no es el factor determinante: es la forma de aplicar la maniobra la que fija el efecto."]],
  "214": ["¿Qué efecto produce el masaje a nivel del tejido articular?",["La resorción de los exudados articulares","La regeneración del cartílago desgastado","El refuerzo de la cápsula articular"],["Sobre la articulación, los efectos recogidos son la reducción de la rigidez, la flexibilización de las adherencias y la resorción de los exudados.","No se describe ninguna acción regeneradora sobre el cartílago; los efectos articulares del masaje son mecánicos y circulatorios.","El masaje flexibiliza la cápsula y las adherencias periarticulares en lugar de reforzarlas."]],
  "215": ["¿Cómo modifica el masaje la actividad del tejido nervioso?",["Sensibilidad de las terminaciones sensoriales disminuida, excitabilidad de los nervios motores aumentada","Sensibilidad de las terminaciones sensoriales disminuida, excitabilidad de los nervios motores disminuida","Sensibilidad de las terminaciones sensoriales aumentada, excitabilidad de los nervios motores aumentada"],["La analgesia proviene del descenso de la sensibilidad de las terminaciones sensoriales, mientras que la excitabilidad de los nervios motores aumenta.","La parte sensorial es correcta, pero la excitabilidad de los nervios motores aumenta en lugar de disminuir.","La excitabilidad motora aumenta, pero la sensibilidad de las terminaciones sensoriales disminuye, lo que explica el efecto analgésico."]],
  "216": ["¿Mediante qué tipo de acción actúa el masaje sobre el tejido visceral, por ejemplo aumentando el peristaltismo intestinal?",["Mediante una acción refleja desencadenada a distancia","Mediante una presión mecánica directa sobre el intestino","Mediante un aumento del flujo sanguíneo mesentérico"],["El efecto visceral del masaje es reflejo: el masaje de evacuación aumenta así el peristaltismo intestinal.","No se trata de un amasamiento directo de la víscera: la respuesta pasa por un reflejo desencadenado desde la pared.","El mecanismo invocado no es vascular; es una respuesta refleja provocada por la maniobra."]],
  "217": ["Entre las contraindicaciones del masaje, ¿cuál depende del estado neurológico de la zona a tratar?",["Las zonas de anestesia o de sensibilidad alterada","Los trastornos graves de la coagulación sanguínea","Las lesiones y las alergias cutáneas de la zona"],["Los cambios de sensibilidad y las zonas de anestesia figuran entre las contraindicaciones; son las únicas de la relación que atañen a la sensibilidad de la región.","Contraindican el masaje, pero en concepto de riesgo hemorrágico, no del estado neurológico local.","Contraindican el masaje en concepto del estado de la piel, y no por un motivo neurológico."]],
  "218": ["Durante la maniobra de drenaje linfático manual, ¿qué fase corresponde a la tensión máxima?",["La fase de empuje activo","La fase de sostén pasivo","La fase de contacto pasivo"],["La maniobra comprende cuatro fases y es el empuje activo el que lleva la tensión a su máximo.","La fase de sostén pasivo abre la maniobra y prepara el tejido sin aplicar la tensión máxima.","La fase de contacto pasivo termina la maniobra con la tensión reducida a cero."]],
  "219": ["¿Qué efecto inmunitario produce el drenaje linfático manual en un paciente inmunodeprimido?",["Un aumento de la producción de IgA","Un aumento de la producción de IgE","Una disminución de las células inmunitarias locales"],["En caso de inmunodeficiencia, se atribuye al drenaje linfático un aumento de la producción de IgA.","Las IgE, ligadas a las reacciones alérgicas, no forman parte de los efectos inmunitarios descritos para esta técnica.","El drenaje mejora al contrario la eficacia de las células inmunitarias presentes en el espacio intersticial."]],
  "220": ["¿Qué tipo de movilización articular se emplea principalmente en los pacientes encamados y hospitalizados?",["La movilización global o funcional","La movilización analítica específica","La movilización pasiva simple"],["La movilización global atañe a más de una articulación y ayuda a conservar un buen esquema motor, de ahí su uso en los pacientes encamados.","La movilización analítica busca un movimiento accesorio preciso de una sola articulación, lo que no es el objetivo aquí.","La movilización simple atañe únicamente a una articulación y a su movimiento fisiológico, sin buscar el esquema motor global."]],
  "221": ["Durante una movilización pasiva, ¿dónde sitúa el fisioterapeuta generalmente el contrapunto?",["Sobre el segmento proximal, que mantiene fijo","Sobre el segmento distal, que desplaza","Sobre la interlínea articular, que comprime"],["El contrapunto es el punto fijo de la movilización; se toma por lo general sobre el segmento proximal del cuerpo.","El segmento distal recibe habitualmente la presa, es decir el punto móvil de la movilización.","No se describe ninguna presa compresiva sobre la interlínea: el contrapunto es una presa de fijación sobre un segmento."]],
  "222": ["¿Cuál es la consecuencia de elegir una presa de brazo de palanca largo durante una movilización pasiva?",["Menos precisión, pero menos fuerza que producir","Más precisión, pero más fuerza que producir","Más precisión y menos fuerza que producir"],["El brazo de palanca largo reduce la fuerza que debe aportar el terapeuta, a costa de una movilización menos precisa.","Es la presa corta, de brazo de palanca corto, la que ofrece más precisión exigiendo más fuerza.","Ninguna presa acumula ambas ventajas: precisión y economía de fuerza varían en sentido inverso."]],
  "223": ["¿Qué progresión describe el curso para la movilización activa?",["De lo activo hacia lo activo asistido o resistido, y después el trabajo funcional","Del trabajo funcional hacia el movimiento activo analítico aislado","Del movimiento pasivo conducido por el terapeuta hacia el activo libre"],["La progresión descrita va de lo activo hacia lo activo asistido o resistido, y después hacia una tarea específica funcional, con aumento progresivo de la amplitud y de la resistencia.","La tarea funcional específica es el término de la progresión, no su punto de partida.","La progresión descrita parte del movimiento ya realizado por el paciente; el movimiento conducido por el terapeuta corresponde a la movilización pasiva."]],
  "224": ["¿En qué situación clínica está indicada la movilización activa?",["Dolor moderado con baja irritabilidad, tras una inmovilización","Dolor intenso con alta irritabilidad, en fase aguda","Paciente poco colaborador, justo después de una cirugía"],["Las indicaciones recogidas son el dolor moderado y la baja irritabilidad, en las fases intermedias de una inmovilización o de una cirugía.","Un dolor intenso y una irritabilidad elevada no figuran entre las indicaciones: el tejido reacciona todavía con demasiada intensidad.","La movilización activa supone un paciente capaz de seguir las instrucciones y de participar activamente en el movimiento."]],
  "225": ["¿Mediante qué mecanismo disminuye el dolor la movilización activa?",["Mediante el bombeo sinovial y el control neuromuscular","Mediante el estiramiento prolongado de las estructuras capsulares","Mediante la disminución de la temperatura articular"],["El movimiento producido por el paciente asegura un bombeo sinovial y mantiene el control neuromuscular, lo que disminuye el dolor.","El estiramiento capsular no es el mecanismo analgésico recogido; la movilización activa previene además la pérdida de extensibilidad capsular.","No se invoca ningún efecto térmico: el efecto analgésico se debe al propio movimiento activo."]],
  "226": ["¿Cuál es el principio de las técnicas de movilización neuromeníngea (neurodinámica)?",["Liberar los puntos de presión que dificultan el deslizamiento del nervio","Estirar el nervio hasta su límite elástico para alargarlo","Fortalecer los músculos inervados para compensar el déficit"],["El nervio atraviesa fascias, músculos y cápsulas que pueden rigidizarse y pinzarlo; esas técnicas liberan los puntos de presión a lo largo de su trayecto.","No se trata de alargar el nervio, sino de restaurar su movimiento allí donde su deslizamiento está impedido.","El fortalecimiento muscular no es el objeto de esas técnicas, que se dirigen al tejido nervioso y a su entorno."]],
  "227": ["¿Por qué se emplean también las técnicas neurodinámicas en dolores nociceptivos que no afectan al tejido nervioso?",["Porque mejoran el umbral del dolor del paciente","Porque aceleran la cicatrización del tejido lesionado","Porque suprimen la compresión del tejido nervioso"],["El curso indica que esas técnicas mejoran el umbral del dolor y reducen así el dolor percibido, incluso cuando el tejido nervioso no está afectado.","No se propone ningún efecto sobre la cicatrización tisular para justificar ese uso ampliado.","Precisamente no hay ninguna compresión nerviosa que levantar en esa situación, puesto que el tejido nervioso no está afectado."]],
  "228": ["Cuando los síntomas del paciente se consideran irritables o graves, ¿cómo debe conducirse la exploración física?",["Limitando las pruebas de movimiento a la aparición de los síntomas","Llevando cada prueba hasta la amplitud máxima disponible","Sustituyendo las pruebas de movimiento por las pruebas de imagen"],["Ante síntomas irritables o graves, las pruebas de movimiento solo se llevan hasta el momento en que los síntomas aparecen.","Llevar las pruebas al máximo expone a agravar un cuadro ya reactivo, lo que la exploración debe precisamente evitar.","No se propone sustituir la exploración física por las pruebas de imagen: lo que se adapta es la conducción de las pruebas."]],
  "229": ["¿Qué inconveniente se asocia a seguir siempre la misma secuencia de preguntas durante la entrevista?",["Encadenar las preguntas sin interpretar las respuestas recibidas","Dejar de lado algunos ámbitos pertinentes de la entrevista","Alargar el tiempo necesario para completar el cuestionario"],["Se corre el riesgo de « prescribir preguntas », es decir de desgranarlas una tras otra sin preguntarse si son útiles ni interpretar lo que se dice.","Es al contrario una ventaja de la secuencia constante: garantiza que se aborden todos los ámbitos pertinentes.","La secuencia habitual ahorra tiempo de recogida; el alargamiento no es el inconveniente descrito."]],
  "230": ["¿En qué momentos debe realizarse la reevaluación del paciente?",["Durante la sesión, tras cada abordaje, al final y al inicio de la siguiente","Solo al final del programa de tratamiento, para medir el resultado","Solo al inicio de cada sesión, antes de aplicar una técnica"],["La reevaluación se efectúa durante la sesión, tras cada abordaje, al final de la sesión y al inicio de la del día siguiente; nunca puede prescindirse de ella.","Esperar al final del programa priva al terapeuta de la información que permite ajustar la atención a lo largo del camino.","Una reevaluación inicial no basta: debe también seguir a cada abordaje y cerrar la sesión."]],
  "231": ["¿En qué consiste la hipótesis de tratamiento en el sistema de categorización de las hipótesis?",["Realizar un tratamiento de prueba desde el primer día para verificar la hipótesis","Elegir de entrada el protocolo estándar correspondiente al diagnóstico","Enumerar las técnicas prohibidas antes de todo contacto con el paciente"],["Desde la primera sesión se aplica un tratamiento de prueba destinado a verificar si la hipótesis formulada se confirma o no.","El razonamiento por hipótesis se opone a la aplicación de un protocolo elegido de antemano, demasiado rígido para cada paciente.","Las precauciones y las contraindicaciones constituyen otra categoría de hipótesis, distinta de la del tratamiento."]],
  "232": ["En el análisis del mapa corporal, ¿en qué orden se consideran las estructuras responsables del dolor?",["De las estructuras situadas bajo el dolor hacia las causas menos probables","De las causas viscerales a descartar hacia las estructuras locales probables","De las estructuras que irradian a distancia hacia las estructuras locales"],["Se empieza por las estructuras situadas bajo la zona dolorosa, las más probables, después las estructuras vecinas y por último las hipótesis menos probables.","Las causas viscerales se cuentan entre las menos probables: se consideran en último lugar, sin olvidarlas por ello.","La musculatura que irradia hacia la zona se examina después de la que se encuentra bajo el dolor, no antes."]],
  "233": ["¿A qué grupo de prejuicios del fisioterapeuta pertenece « la falacia del coste hundido »?",["A los prejuicios ligados al razonamiento","A los prejuicios ligados a las creencias","A los prejuicios ligados a los pronósticos"],["Figura entre los prejuicios del razonamiento, con la falta de parsimonia y el hecho de no seguir el estado actual de los conocimientos y de las pruebas.","El grupo de las creencias reúne otros sesgos del terapeuta, como el sesgo de confirmación, y no los defectos en la conducción misma del razonamiento.","El grupo de los pronósticos atañe a la honestidad y a la explicación de la historia natural del problema al paciente."]],
  "234": ["¿Por qué influye la creencia del paciente sobre su problema en el razonamiento clínico?",["Porque muchos se autodiagnostican a partir de informaciones poco fiables","Porque determina la duración real de la cicatrización de los tejidos","Porque dispensa de explorar los factores sociales del paciente"],["El conocimiento que el paciente tiene de su problema cuenta: son numerosos los que se autodiagnostican por internet, donde no todas las informaciones son fiables.","Las creencias no modifican la biología de la reparación; pesan sobre la manera en que el paciente presenta y comprende su problema.","La creencia del paciente no sustituye a ningún otro factor de influencia: el nivel cultural, el idioma o los recursos cuentan igualmente."]],
  "235": ["¿Qué busca el fisioterapeuta cuando identifica « signos comparables » durante la exploración objetiva?",["Referencias de calidad o de cantidad de movimiento, como una asimetría","Signos que obliguen a interrumpir de inmediato la exploración física","Resultados de pruebas de imagen concordantes con la queja expresada"],["Los signos comparables son referencias extraídas de la propia exploración física: calidad o cantidad del movimiento, asimetrías.","Interrumpir la exploración corresponde a las precauciones y a los indicadores de alarma, no a la búsqueda de signos comparables.","Los signos comparables se obtienen mediante las pruebas realizadas, y no mediante las pruebas complementarias que aporta el paciente."]],
  "236": ["La electroterapia es la aplicación de una corriente eléctrica o de una energía electromagnética que produce reacciones fisiológicas en el organismo. ¿Con qué fines se aprovechan esas reacciones?",["Con fines terapéuticos, preventivos y diagnósticos","Con fines terapéuticos, preventivos y antisépticos","Con fines terapéuticos, diagnósticos y quirúrgicos"],["La definición recoge esos tres usos: se aprovechan las reacciones fisiológicas inducidas para tratar, para prevenir y para explorar.","La desinfección no forma parte de los usos recogidos; la tercera vertiente de la definición es el diagnóstico, junto al tratamiento y a la prevención.","La electroterapia no se presenta como un gesto quirúrgico; es la prevención la que completa aquí el tratamiento y el diagnóstico."]],
  "237": ["A nivel de los tejidos, ¿qué fenómeno provoca en primer lugar el paso de la corriente eléctrica?",["Un desplazamiento de iones como el sodio, el potasio, el calcio y el cloro","Una desnaturalización de las proteínas de la membrana de las células excitables","Una liberación de neuropéptidos por las terminaciones nerviosas libres"],["La corriente es un flujo de cargas: pone en movimiento los iones de los medios atravesados, lo que condiciona después las respuestas sensoriales y motoras.","No hay ninguna destrucción proteica en juego: la corriente modifica el estado eléctrico de la membrana, no altera su estructura.","La circulación de los neuropéptidos, de las hormonas y de los lípidos puede verse favorecida, pero es una consecuencia del desplazamiento iónico, no el fenómeno inicial."]],
  "238": ["La impedancia de los tejidos al paso de la corriente genera respuestas a veces indeseables. ¿Cuáles?",["Un calentamiento y una estimulación de las terminaciones nociceptivas","Una licuefacción de los tejidos con rechazo de los iones negativos","Una coagulación local acompañada de un desprendimiento de oxígeno"],["La resistencia que oponen los tejidos disipa energía en forma de calor y puede reclutar las terminaciones nociceptivas, de ahí una sensación desagradable.","Licuefacción y rechazo de iones negativos son reacciones de electrodo propias de las corrientes con efecto polar, no una consecuencia de la impedancia tisular.","Coagulación y desprendimiento de oxígeno corresponden también a una reacción de electrodo, y no a la resistencia que los tejidos oponen a la corriente."]],
  "239": ["Al margen del desencadenamiento de un potencial de acción, ¿qué efecto puede ejercer la corriente eléctrica sobre la membrana de una célula excitable?",["Modificar su excitabilidad facilitándola o dificultándola","Invertir de forma duradera la polaridad de reposo de la célula","Suprimir el periodo refractario que sigue a la despolarización"],["La corriente actúa como un modulador: hace que el tejido sea más o menos fácil de excitar, lo que permite por ejemplo rebajar el umbral del dolor.","No se describe ninguna inversión duradera: la célula recupera su estado de partida, y la corriente solo facilita o dificulta su excitación.","El periodo refractario es una propiedad de la membrana que la corriente no suprime; el terapeuta debe al contrario tenerlo en cuenta."]],
  "240": ["¿Por qué es esencial conocer los parámetros necesarios para la activación del potencial de acción?",["Porque permite ser selectivo según el tejido buscado y el efecto deseado","Porque la duración de la sesión determina por sí sola la respuesta","Porque los ajustes modifican la conductividad propia de cada tejido"],["Son los parámetros elegidos los que deciden el tejido realmente activado, y por tanto el efecto terapéutico obtenido; sin ellos la aplicación es ciega.","La duración de la aplicación no basta: es la combinación de las características de la corriente la que condiciona la activación de un tejido dado.","La conductividad depende de la composición del propio tejido; los ajustes no la cambian, solo deciden qué tejido se logra excitar."]],
  "241": ["La electroterapia alivia el dolor por dos vías: la mejora de la sensación o de la percepción dolorosa y:",["La regeneración de los tejidos dañados por la lesión","La hiperpolarización permanente de las fibras motoras","La elevación progresiva del umbral motor del músculo"],["La segunda vía pasa por la reparación del propio tejido: al mejorar su estado se agota la fuente del dolor.","La hiperpolarización es un efecto del polo positivo de una corriente con efecto polar, junto con la vasoconstricción y la sedación; no es una de las dos vías de analgesia descritas.","El umbral motor atañe al reclutamiento de la contracción y no al tratamiento del dolor."]],
  "242": ["¿A qué corresponde el mecanismo metabólico de la analgesia por electroterapia?",["A la aceleración de la síntesis y de la destrucción por el aflujo circulatorio","A la transmisión preferente de las informaciones táctiles hasta el cerebro","A la elevación del umbral del dolor por la conjunción de las otras dos vertientes"],["El aumento del flujo circulatorio acelera los procesos de síntesis y de destrucción: es la vertiente metabólica de la analgesia.","Es la vertiente neurofisiológica, la de la teoría del control de la compuerta, distinta del mecanismo metabólico.","Esa conjunción define el mecanismo mixto, que el curso distingue del mecanismo puramente metabólico."]],
  "243": ["Entre los efectos obtenidos sobre un tejido lesionado, ¿cuál atribuye el curso a la estimulación eléctrica?",["Una reducción de los espasmos musculares con mejora de la vascularización","Un refuerzo del tono de reposo con enlentecimiento de la circulación local","Una retracción de las fibras conjuntivas con endurecimiento del tejido tratado"],["El curso incluye la reducción de los espasmos musculares y la mejora de la vascularización de los tejidos entre los efectos obtenidos sobre un tejido lesionado.","Es lo contrario de lo descrito: la estimulación relaja el músculo y aumenta el flujo sanguíneo local, condición del aporte de nutrientes y de oxígeno al tejido.","No se describe ninguna remodelación retráctil: el efecto buscado en el tejido lesionado es circulatorio y antiespasmódico, no mecánico."]],
  "244": ["Se asignan tres finalidades a la electroterapia destinada a provocar una contracción muscular: el fortalecimiento en caso de atrofia, la potenciación y:",["La toma de conciencia de la contracción","La reducción de la espasticidad del músculo tratado","El alargamiento del tendón por estiramiento repetido"],["El tercer objetivo es pedagógico: la contracción provocada ayuda al paciente a percibir su músculo y a reclutarlo después voluntariamente.","La lucha contra la espasticidad no figura entre las tres finalidades recogidas para la contracción provocada.","El estiramiento del tendón no es un objetivo de la contracción provocada, que se dirige al propio músculo."]],
  "245": ["¿Con qué criterio se distingue la corriente pulsada de la corriente continua?",["Fluye por impulsos separados por tiempos sin corriente","Cambia el sentido del flujo en cada impulso emitido","Emite una intensidad creciente en cada impulso"],["Es la interrupción del flujo lo que define la corriente pulsada: impulsos sucesivos entrecortados por periodos de ausencia de corriente.","La inversión del sentido del flujo define la corriente alterna, y no el carácter pulsado, que depende únicamente de la interrupción de la corriente entre los impulsos.","La intensidad no interviene en esa clasificación, que se basa únicamente en la continuidad o no del flujo."]],
  "246": ["Entre los efectos siguientes, ¿cuál figura entre los efectos fisiológicos de las corrientes con efecto polar?",["Una acción antiinflamatoria y antiedematosa","Una elevación térmica profunda de los tejidos atravesados","Una frecuencia de batido resultante de dos corrientes"],["A las corrientes con efecto polar se les atribuye una acción antiinflamatoria y antiedematosa, junto con la reparación tisular y la analgesia.","La elevación térmica profunda no se cuenta entre los efectos de las corrientes con efecto polar: corresponde a las técnicas de diatermia.","Un batido resulta del encuentro de dos corrientes: es un procedimiento de producción de la corriente, no un efecto fisiológico polar."]],
  "247": ["¿A qué tipo de corriente se vincula la iontoforesis?",["A la corriente continua","A la corriente alterna","A la corriente pulsada"],["La iontoforesis supone un transporte de iones siempre en el mismo sentido, lo que la vincula a la corriente continua.","La corriente alterna cambia de sentido con el tiempo: no arrastraría los iones en una dirección constante, condición sin embargo indispensable para el transporte transcutáneo.","La corriente pulsada se sitúa del lado del control del dolor y de la contracción muscular, y no del transporte transcutáneo de sustancias ionizadas."]],
  "248": ["Para la cicatrización de los tejidos y el tratamiento de los edemas agudos, ¿cómo se aplica la corriente pulsada?",["En forma de impulsos de fase única","En trenes de frecuencia media superpuestos","En alternancia simétrica equilibrada"],["Esas dos indicaciones recurren a una corriente pulsada de fase única: el flujo circula en un solo sentido, lo que conserva bajo el electrodo el efecto polar buscado.","La superposición de dos frecuencias medias caracteriza las corrientes interferenciales, empleadas con otros fines.","Una alternancia simétrica equilibra las dos fases y anula la polaridad resultante, lo que priva a la aplicación del efecto buscado aquí."]],
  "249": ["Cuando la frecuencia aplicada se vuelve demasiado elevada, muchos impulsos ya no desencadenan un potencial de acción. ¿Por qué?",["Porque la membrana no repolarizada permanece en periodo refractario","Porque la intensidad emitida disminuye cuando la frecuencia aumenta","Porque los impulsos próximos entre sí se anulan unos a otros"],["Mientras la repolarización no ha concluido, la membrana no acepta ningún nuevo estímulo: los impulsos demasiado próximos caen en ese periodo.","Frecuencia e intensidad son dos parámetros independientes: aumentar una no reduce la otra.","Los impulsos no se anulan mutuamente; es el estado de la membrana en el momento del estímulo el que decide la respuesta."]],
  "250": ["En una corriente emitida en trenes de impulsos, ¿a qué corresponde el tiempo muerto?",["Al periodo sin corriente que separa dos trenes de impulsos","Al tiempo durante el cual la corriente circula en cada impulso","Al lapso que separa dos impulsos consecutivos de un tren"],["El tiempo muerto es el intervalo de ausencia total de estimulación que se intercala entre dos trenes sucesivos.","Es la definición de la duración de la fase, expresada en milisegundos, que se mide dentro del propio impulso.","Es el intervalo entre impulsos, o pausa: separa dos impulsos, no dos trenes enteros."]],
  "251": ["Entre las situaciones siguientes, ¿cuál figura entre las contraindicaciones generales de la electroterapia?",["Un proceso tumoral en evolución","Una cicatriz cerrada y antigua","Una amiotrofia tras una inmovilización"],["Los procesos tumorales forman parte de las contraindicaciones generales, al igual que las infecciones activas y los dispositivos implantados.","Son las heridas abiertas las que contraindican la aplicación, y no una cicatriz cerrada desde hace tiempo.","La amiotrofia consecutiva a una inmovilización constituye al contrario una indicación clásica de la contracción provocada."]],
  "252": ["¿En qué órdenes de conocimiento fundamenta la definición de la fisioterapia respiratoria las técnicas físicas aplicadas al paciente?",["La fisiopatología respiratoria y los cuidados psicoemocionales del paciente","La fisiopatología respiratoria y la biomecánica costovertebral","La anatomía de las vías aéreas y la farmacología de los broncodilatadores"],["La definición asocia explícitamente el conocimiento de la fisiopatología respiratoria al de los cuidados psicoemocionales del paciente.","La mecánica costovertebral no se cita como base de la disciplina: la segunda vertiente recogida es la dimensión psicoemocional del cuidado.","El tratamiento farmacológico no entra en la definición, que se basa en técnicas físicas y no en una prescripción farmacológica."]],
  "253": ["¿Qué finalidades asigna la definición de la fisioterapia respiratoria ante los trastornos que atiende?",["Prevenir, curar o a veces simplemente estabilizar esos trastornos","Detectar, curar y compensar de forma duradera esos trastornos","Prevenir, curar y suprimir toda recidiva de esos trastornos"],["La definición enuncia esos tres niveles de ambición, y la estabilización sigue siendo un objetivo legítimo cuando la curación no es alcanzable.","El cribado no forma parte de las finalidades enunciadas, y la definición habla de estabilizar el trastorno más que de compensarlo.","No se anuncia ninguna abolición de las recidivas: la definición admite al contrario que se pueda limitar a estabilizar el trastorno."]],
  "254": ["¿Qué conjunto designa la definición de la fisioterapia respiratoria como campo de acción de la disciplina?",["El sistema toracopulmonar","El sistema cardiorrespiratorio","Las vías aéreas superiores"],["La definición se refiere a los trastornos que afectan al sistema toracopulmonar, es decir al pulmón y al tórax que lo contiene.","La vertiente cardiaca no se incluye en el campo enunciado, que sigue centrado en el tórax y el pulmón.","El campo descrito no se limita a las vías aéreas altas: engloba el conjunto toracopulmonar."]],
  "255": ["Más allá de sus objetivos técnicos, ¿qué finalidad general asigna el curso a la fisioterapia respiratoria?",["Promover la calidad de vida de los pacientes con trastornos respiratorios","Reducir la duración del ingreso de los pacientes con trastornos respiratorios","Restaurar la integridad del tejido pulmonar lesionado en esos mismos pacientes"],["El curso cierra el enunciado de sus objetivos indicando que busca promover la calidad de vida de los pacientes con trastornos del sistema respiratorio.","La duración de la estancia no es la finalidad enunciada: el curso razona en términos de vivencia y de función del paciente.","No se promete ninguna reparación del parénquima: la disciplina actúa sobre la función respiratoria, no sobre la propia lesión tisular."]],
  "256": ["El curso sitúa la disminución de la hiperinsuflación pulmonar bajo cuál de sus grandes efectos fisiológicos?",["La mejora de la ventilación pulmonar","La mejora del intercambio gaseoso alveolar","La permeabilización de las vías respiratorias"],["La reducción del volumen de aire atrapado en el pulmón se presenta como un componente de la mejora de la ventilación pulmonar.","Ese efecto atañe a la transferencia de los gases entre alvéolo y capilar, y no al grado de distensión del pulmón.","Ese efecto atañe a la evacuación de las secreciones bronquiales, un mecanismo distinto de la reducción de la distensión pulmonar."]],
  "257": ["¿En qué marco sitúa la OMS la importancia de la rehabilitación?",["En el marco de la cobertura sanitaria universal","En el marco de los programas de cuidados paliativos","En el marco de la salud laboral del personal asistencial"],["El curso recoge que la OMS subraya la importancia de la rehabilitación en el marco de la cobertura sanitaria universal.","Los cuidados paliativos buscan el confort en fase avanzada de enfermedad; no es el marco en el que se sitúa la rehabilitación.","La salud laboral atañe a la prevención de los riesgos profesionales y no corresponde al marco invocado aquí."]],
  "258": ["¿Qué busca el objetivo de desarrollo sostenible al que la OMS vincula la rehabilitación?",["Garantizar una vida sana y promover el bienestar a todas las edades","Reducir las desigualdades de acceso a la atención entre países","Asegurar una educación de calidad a lo largo de toda la vida"],["El curso precisa que ese objetivo busca garantizar una vida sana y promover el bienestar de todos a todas las edades.","La reducción de las desigualdades entre países constituye un objetivo distinto, que no es el citado para la rehabilitación.","La educación de calidad corresponde a otro objetivo, sin relación con la finalidad sanitaria mencionada en el curso."]],
  "259": ["¿Qué lugar ocupan hoy las afecciones neurológicas en el mundo?",["Son la principal causa de enfermedad y de discapacidad","Son la primera causa de ingreso hospitalario no programado","Son la segunda causa de discapacidad después de los cánceres"],["El curso las designa como la primera causa de enfermedad y de discapacidad a escala mundial.","El recurso hospitalario urgente no es el indicador con el que el curso sitúa su peso mundial.","El curso no las sitúa ni en segundo lugar ni detrás de los cánceres por la discapacidad que ocasionan."]],
  "260": ["¿Hasta dónde puede llegar la modificación producida por la plasticidad neuronal?",["Hasta la modificación de factores genéticos","Hasta el solo refuerzo de las sinapsis existentes","Hasta la sola reorganización de las redes corticales"],["La definición recogida precisa que el cambio puede llegar a modificar factores genéticos.","El refuerzo de las sinapsis ya existentes representa solo una parte de los cambios descritos.","Limitar el cambio a una reorganización cortical subestima la profundidad de lo que describe el curso."]],
  "261": ["¿A qué estímulos responde el sistema nervioso cuando pone en juego su plasticidad?",["A estímulos tanto externos como internos","Únicamente a los estímulos externos procedentes del entorno","Únicamente a los estímulos internos de origen metabólico"],["El curso asocia el cambio plástico a estímulos de origen tanto externo como interno.","Restringir la plasticidad a las solicitaciones venidas de fuera descarta indebidamente el origen interno.","Los estímulos internos cuentan, pero no son los únicos que provocan el cambio."]],
  "262": ["Según el curso, ¿qué produce las modificaciones de la neuroplasticidad?",["Las experiencias ambientales y una mediación apropiada","La maduración genéticamente programada del sistema nervioso central","La administración repetida de tratamientos farmacológicos dirigidos"],["El curso atribuye esas modificaciones a las experiencias vividas en el entorno, asociadas a una mediación apropiada.","Una maduración puramente programada no basta: el papel de la experiencia y de la mediación es determinante.","El curso no hace descansar las modificaciones de neuroplasticidad en un tratamiento farmacológico."]],
  "263": ["¿Cómo caracteriza el curso la plasticidad gracias a la cual el cerebro se adapta a los estímulos?",["Es una plasticidad que sigue a la actividad","Es una plasticidad que precede a la actividad","Es una plasticidad independiente de la actividad"],["El curso subraya que esa capacidad de adaptación sigue a la actividad realizada por el sujeto.","La plasticidad descrita se instala a continuación de la actividad, y no antes de que esta tenga lugar.","Hacer la plasticidad independiente de la actividad contradice el vínculo que el curso establece entre ambas."]],
  "264": ["Según el curso, ¿en qué dos grandes partes se divide el sistema nervioso?",["El sistema nervioso central y el sistema nervioso periférico","El sistema nervioso somático y el sistema nervioso autónomo","El sistema nervioso sensitivo y el sistema nervioso motor"],["El curso divide el sistema nervioso en un componente central y un componente periférico.","Esa oposición separa el mando voluntario del mando vegetativo, pero no es la división presentada.","Sensitivo y motor designan funciones y no las dos grandes divisiones recogidas aquí."]],
  "265": ["En el paciente neurológico, ¿cuál de estos elementos corresponde a la afectación subyacente y no a lo que se observa de entrada?",["Una lesión de la médula espinal","Una imprecisión de la sensorialidad","Una perturbación de la coordinación"],["La lesión medular forma parte de las afectaciones causales situadas por delante de los signos constatados.","Se trata de un signo percibido durante la exploración del paciente, no de la causa que lo produce.","La perturbación de la coordinación es una de las manifestaciones constatadas, no su origen."]],
  "266": ["Además de la lesión y del daño, ¿qué situación entra en el campo de estudio de la neurofisioterapia?",["El funcionamiento anormal de las estructuras nerviosas","El envejecimiento fisiológico de las vías motoras","La fatiga muscular de origen periférico"],["La disciplina estudia también las consecuencias de un funcionamiento anormal de las estructuras del sistema nervioso.","El envejecimiento normal no se inscribe en el objeto de estudio definido para esta disciplina.","La fatiga del músculo corresponde a otro campo: la definición versa sobre las estructuras nerviosas."]],
  "267": ["Según la definición general de la fisioterapia invasiva, ¿qué zonas pueden tratarse sin ecógrafo?",["Las zonas superficiales y fácilmente accesibles a la aguja","Las zonas profundas situadas lejos de un trayecto vasculonervioso","Las zonas ya tratadas anteriormente con esta técnica"],["El curso recomienda el ecógrafo por la seguridad, la precisión y la eficacia del gesto, pero admite que las zonas superficiales y fácilmente accesibles se traten sin él; la electrólisis percutánea y la neuromodulación, en cambio, imponen la guía ecográfica.","La profundidad del tejido es al contrario lo que hace necesaria la localización ecográfica: la lejanía de un trayecto vasculonervioso no es el criterio recogido.","La anterioridad del tratamiento no interviene: solo se recoge como condición el carácter superficial y accesible de la zona."]],
  "268": ["¿Por qué algunas agujas de fisioterapia invasiva están recubiertas de plata o de platino?",["Para mejorar su conductividad eléctrica","Para hacerlas más resistentes a la penetración","Para adaptar su calibre al tejido buscado"],["Ese recubrimiento de plata o de platino tiene por objeto mejorar la conductividad eléctrica de la aguja cuando se le aplica una corriente.","Es el acero inoxidable, material de base de las agujas, el que les asegura solidez y resistencia a la rotura durante el procedimiento.","La adaptación a la profundidad del tejido pasa por la elección del diámetro de la aguja, no por un recubrimiento de superficie."]],
  "269": ["¿Qué diámetro presentan las agujas más empleadas en fisioterapia invasiva?",["Entre 0,25 y 0,35 mm","Entre 0,10 y 0,20 mm","Entre 0,50 y 0,60 mm"],["Las agujas más habituales tienen un diámetro de 0,25 a 0,35 mm, y el calibre varía después según la zona y la profundidad del tejido.","Ese calibre queda por debajo del de las agujas más habituales, cuyo diámetro empieza en 0,25 mm.","Ese calibre supera el de las agujas más habituales, cuyo diámetro se detiene en 0,35 mm, y las más gruesas se reservan a los tejidos profundos."]],
  "270": ["¿Con qué termina el procedimiento tipo de una sesión de fisioterapia invasiva, y con qué finalidad?",["Con un tratamiento posinvasivo destinado a evitar los dolores posteriores","Con la obtención del consentimiento informado, una vez informado el paciente","Con la desinfección de las manos del fisioterapeuta y de la piel del paciente"],["La última etapa del procedimiento es un tratamiento posinvasivo, cuyo objetivo es prevenir los dolores que aparecen después de la sesión.","El consentimiento informado es la quinta etapa del procedimiento, obtenida antes, justo después de haber informado al paciente de lo que se va a realizar.","La higiene y la desinfección pertenecen a las etapas de preparación, antes de la colocación del paciente y de la ejecución del gesto."]],
  "271": ["¿A qué corresponde el síndrome de dolor miofascial (SDM)?",["Al conjunto de los síntomas y signos provocados por un punto gatillo miofascial","A una contractura muscular difusa de origen central, sin foco localizado","A un dolor articular que irradia hacia las masas musculares vecinas"],["El SDM se define como el conjunto de los síntomas y signos causados por un punto gatillo, foco de hiperirritabilidad musculoesquelética.","El SDM parte al contrario de un foco localizado de hiperirritabilidad en el músculo, y no de un origen central difuso.","El dolor del SDM nace del propio músculo y de su punto gatillo, y no de un sufrimiento articular irradiado."]],
  "272": ["¿Cuál de estos elementos figura entre los tres criterios clínicos mínimos de diagnóstico del síndrome de dolor miofascial?",["El dolor referido tras la palpación del punto doloroso","La reproducción del dolor habitual del paciente","La respuesta de espasmo local a la palpación"],["Es el tercero de los criterios mínimos, junto con la banda tensa palpable y los puntos hipersensibles situados dentro de esa banda.","La reproducción del dolor del paciente pertenece a los seis criterios de confirmación, y no a los tres criterios mínimos.","La respuesta de espasmo local abre también la relación de los criterios de confirmación, justo después de los tres criterios mínimos."]],
  "273": ["¿Qué estructuras del citoesqueleto estira la aguja durante una punción seca?",["La titina y la banda Z del sarcómero","La actina y la miosina de las miofibrillas","El colágeno del endomisio muscular"],["Entre los efectos mecánicos de la punción seca figura el estiramiento de las estructuras del citoesqueleto, es decir la titina y la banda Z.","Actina y miosina son las proteínas contráctiles del sarcómero, y no las estructuras del citoesqueleto a las que apunta ese efecto.","Ese colágeno pertenece al tejido conjuntivo que envuelve la fibra, fuera del citoesqueleto propiamente dicho."]],
  "274": ["¿Qué fibras nerviosas estimula la punción seca entre sus efectos neurofisiológicos?",["Las fibras Aδ y C","Las fibras Aβ y Aδ","Las fibras Aα y C"],["La estimulación de las fibras Aδ y C se incluye entre los efectos neurofisiológicos de la punción seca, junto con la reducción de la nocicepción periférica.","Las fibras Aβ, de gran calibre, no figuran en la relación del curso, que recoge únicamente las dos fibras nociceptivas.","Las fibras C sí están implicadas, pero son las fibras Aδ, y no las Aα, las que completan la relación enseñada."]],
  "275": ["¿Qué efecto ejerce la punción seca sobre las regiones límbicas como la amígdala y el córtex prefrontal?",["Una disminución de su actividad","Un aumento de su actividad","Una actividad estrictamente inalterada"],["Entre los efectos neurofisiológicos figura una disminución de la actividad de las regiones límbicas, amígdala y córtex prefrontal incluidos.","El efecto descrito va en sentido contrario: la actividad de las regiones límbicas baja por efecto de la punción seca.","La modulación no se limita a la médula y al córtex sensorial: se describe también una repercusión límbica."]],
  "276": ["¿En qué condiciones contraindica un tatuaje la punción seca?",["Únicamente cuando cubre la zona a tratar","Cualquiera que sea su ubicación en el cuerpo","Únicamente cuando tiene menos de seis meses"],["El tatuaje se recoge como contraindicación solo cuando se sitúa sobre la zona a tratar.","Un tatuaje situado lejos del punto de punción no entra en las contraindicaciones recogidas.","Es la localización del tatuaje, y no su antigüedad, lo que fundamenta la restricción enseñada."]],
  "277": ["¿Qué beneficio particular aportan las corrientes bifásicas simétricas en electropunción seca?",["Reducen el dolor sentido tras la punción","Producen un efecto polar en la punta de la aguja","Permiten superar el umbral doloroso del paciente"],["Entre las recomendaciones recogidas, las corrientes bifásicas simétricas se eligen porque reducen el dolor pospunción.","Un efecto polar supone una corriente que circula en un solo sentido; una corriente bifásica simétrica no lo produce.","La intensidad depende del umbral del paciente y el curso recomienda expresamente emplear una corriente no dolorosa."]],
  "278": ["¿Qué parámetros de sesión se recomiendan en electropunción seca?",["Unos 30 minutos de tratamiento, 1 a 3 sesiones por semana","Unos 10 minutos de tratamiento, 1 a 3 sesiones por semana","Unos 30 minutos de tratamiento, 4 a 5 sesiones por semana"],["Las recomendaciones recogidas establecen una duración de unos 30 minutos y un ritmo de 1 a 3 sesiones semanales.","El ritmo semanal es correcto, pero la duración enseñada es mucho más larga, del orden de media hora.","La duración es correcta, pero el ritmo enseñado no supera las tres sesiones por semana."]],
  "279": ["En electropunción seca, ¿a qué corresponde la aplicación de una frecuencia de 15 Hz?",["A la liberación de diamorfina","A la liberación de encefalinas","A la combinación de dos efectos"],["La frecuencia de 15 Hz se asocia a la liberación de diamorfina en la activación del sistema de manejo del dolor.","Las encefalinas, liberadas junto con las endorfinas, se vinculan a las frecuencias bajas de 2 a 4 Hz.","Esa combinación de los dos efectos analgésicos se obtiene a 100 Hz, frecuencia claramente más elevada."]],
  "280": ["Según el curso, ¿con qué condición se mantienen y ganan eficacia los efectos terapéuticos de la electrólisis percutánea?",["Cuando se asocian a otros abordajes como el ejercicio físico","Cuando se aumenta el número de agujas insertadas simultáneamente","Cuando se aumenta la intensidad de la corriente en cada nueva sesión"],["Esos efectos se mantienen en el tiempo y se vuelven más eficaces cuando se combinan con otras alternativas terapéuticas, el ejercicio físico en particular.","La durabilidad de los efectos no se relaciona nunca con el número de agujas empleadas durante la sesión.","No se presenta ningún aumento progresivo de la intensidad de una sesión a otra como factor de durabilidad."]],
  "281": ["¿Qué mecanismos incluye el curso bajo el efecto de modulación del dolor de la electrólisis percutánea?",["Receptores opioides endógenos, canales iónicos y sustancias analgésicas","Receptores opioides endógenos, canales iónicos y fibras de gran calibre","Receptores opioides endógenos, canales de calcio y sustancias vasoactivas"],["La modulación del dolor reúne la activación de los receptores opioides endógenos, la modulación de los canales iónicos y el estímulo de la liberación de sustancias analgésicas.","Los dos primeros elementos son correctos, pero el reclutamiento de las fibras de gran calibre corresponde a la teoría de la compuerta y no se cita aquí.","El curso se refiere a los canales iónicos en sentido amplio, y las sustancias cuya liberación describe son analgésicas, no vasoactivas."]],
  "282": ["¿Cuál de estas situaciones figura entre las contraindicaciones de la electrólisis percutánea?",["Un episodio de fiebre","Un enrojecimiento cutáneo","Una lesión bursal"],["La fiebre se enumera entre las contraindicaciones de la electrólisis percutánea, junto con el embarazo y el marcapasos.","El enrojecimiento de la piel se incluye entre las precauciones a vigilar, y no entre las contraindicaciones.","Las lesiones bursales constituyen al contrario una indicación reconocida de la técnica."]],
  "283": ["¿Qué mecanismo de la neuromodulación percutánea pone en juego la plasticidad neuronal y la sumación temporal para mejorar un dolor crónico?",["La desensibilización central","La desensibilización periférica","La plasticidad cortical adaptativa"],["Reduce la sobrecarga de la señal dolorosa que había vuelto demasiado sensible al sistema nervioso, actuando sobre la plasticidad neuronal y la sumación temporal.","Normaliza la excitabilidad de los nervios irritados a nivel local, y no la sensibilización mantenida por el sistema nervioso central.","Modifica la representación cortical del cuerpo y actúa sobre todo en los dolores difusos o fantasmas."]],
  "284": ["¿Cuál de estas situaciones constituye una contraindicación de la neuromodulación percutánea?",["El uso reciente de otra técnica invasiva en la región","Un dolor neuropático instaurado desde hace varios meses","Una intervención quirúrgica prevista en las próximas semanas"],["Esa situación se enumera entre las contraindicaciones de la neuromodulación percutánea, al igual que la infección activa de la zona.","Los dolores neuropáticos figuran al contrario entre las indicaciones recogidas para esta técnica.","El periodo preoperatorio se presenta como una indicación de la neuromodulación, y no como una contraindicación."]],
  "285": ["¿Qué papel atribuye el curso a la nocicepción?",["La recepción o la producción, la conducción y la transmisión del mensaje en forma de señal eléctrica","La producción, el almacenamiento y después la liberación diferida de los mediadores químicos del mensaje nocivo","La recepción del mensaje nocivo y su conversión inmediata en una respuesta motora refleja"],["La nocicepción se define por esos tres tiempos: recepción o producción del mensaje y después su conducción y su transmisión en forma de señal eléctrica.","Ningún almacenamiento diferido entra en esa definición: el mensaje se transporta de inmediato en forma de señal eléctrica.","No se describe ningún circuito motor en la nocicepción: el mensaje recibido se conduce y se transmite, no se convierte en una orden motora."]],
  "286": ["¿Cómo se define un nociceptor?",["Como una neurona específica encargada de captar los estímulos potencialmente nocivos","Como un receptor membranario aislado, desprovisto de prolongación nerviosa propia","Como una terminación nerviosa libre desprovista de umbral de activación propio"],["El nociceptor se presenta como una neurona especializada en la captación de los estímulos potencialmente nocivos.","El receptor membranario es solo un elemento del nociceptor: este es una célula nerviosa entera, no un receptor aislado.","Los receptores membranarios del nociceptor poseen al contrario un umbral de activación, más elevado que el de otras neuronas."]],
  "287": ["Una vez activados sus receptores membranarios, ¿qué hace la neurona con el estímulo recibido?",["Lo transforma en un potencial de acción que se propaga hasta el otro extremo de la célula","Lo conduce tal cual, en su forma mecánica o térmica, hasta la terminación","Modifica de forma duradera el umbral de sus receptores para los estímulos siguientes"],["El estímulo se convierte en un potencial de acción, es decir un cambio del potencial eléctrico de membrana que alcanza el otro extremo de la neurona.","El estímulo no se transporta en su forma de origen: la neurona lo convierte primero en una señal eléctrica.","No se describe ninguna modificación duradera del umbral en esa etapa: el estímulo se convierte y después se propaga a lo largo de la célula."]],
  "288": ["¿Cómo pasa el mensaje de una neurona a la neurona siguiente?",["Mediante neurotransmisores liberados en el espacio sináptico y captados por la neurona siguiente","Mediante la propagación directa de la corriente eléctrica a través de las dos membranas adosadas","Mediante la fusión de las dos terminaciones nerviosas a nivel de la sinapsis"],["El curso describe la liberación de neurotransmisores en el espacio sináptico, donde los receptores membranarios de la neurona siguiente los captan.","El paso de una neurona a otra no es eléctrico, sino químico, puesto que un espacio separa ambas células.","Las dos neuronas permanecen separadas por el espacio sináptico: no se describe ninguna fusión membranaria entre ellas."]],
  "289": ["¿Con qué condición transmite el nociceptor de segundo orden la información hacia el tálamo?",["Si el estímulo nocivo recibido es suficientemente importante","Si el estímulo es mecánico más que químico","Si varios nociceptores de primer orden convergen"],["El curso condiciona ese relevo a la importancia del estímulo: si lo es bastante, la información prosigue su camino hacia los niveles superiores.","La naturaleza mecánica, térmica o química del estímulo no interviene en ese relevo: solo cuenta la importancia del mensaje recibido.","No se describe ningún fenómeno de sumación entre varias fibras de primer orden como condición de ese relevo."]],
  "290": ["¿Qué relación establece el curso entre la información nociceptiva y el dolor?",["La información nociceptiva solo se convierte en dolor si el córtex la interpreta así","Toda información nociceptiva que llega al tálamo se siente como un dolor","El dolor queda constituido desde la activación de los receptores del nociceptor"],["El mensaje nociceptivo y el dolor se distinguen: es a nivel cortical donde la información se interpreta como dolorosa, o no.","El paso por ese relevo no determina por sí solo la percepción: la información puede no interpretarse como dolorosa.","La activación periférica produce un mensaje nociceptivo, que todavía no equivale a un dolor."]],
  "291": ["En ausencia de actividad de las fibras C, ¿qué mantiene silenciosa la vía del dolor?",["Una interneurona inhibidora, tónica, que suprime la vía ascendente","Una inhibición ejercida de forma continua por el tálamo sobre el asta dorsal","El pequeño diámetro de las fibras C, insuficiente para franquear el relevo medular"],["Mientras las fibras C no aportan ningún mensaje, esa interneurona permanece activa de forma permanente y suprime la vía: ninguna señal parte hacia el cerebro.","La inhibición en juego aquí es local y medular; el tálamo es un relevo ascendente, no la fuente de ese bloqueo.","El diámetro de las fibras no explica ese silencio: las fibras C franquean ese relevo cuando se activan."]],
  "292": ["¿Qué relación establece el curso entre la importancia de una lesión y la intensidad del dolor?",["Una lesión, incluso importante, puede acompañarse de un dolor leve o ausente","La intensidad del dolor refleja fielmente la extensión de la afectación tisular","Todo dolor persistente supone una lesión visible en las pruebas de imagen"],["El curso ilustra la disociación entre lesión y dolor: una afectación tisular grave puede vivirse con poco dolor.","Es precisamente la proporcionalidad lo que el curso descarta, con ejemplos.","Nada en el curso subordina la persistencia de un dolor a la presencia de una lesión visible: la imagen y la queja se disocian precisamente allí."]],
  "293": ["¿Qué muestran las resonancias lumbares realizadas en personas sin ningún síntoma?",["Las anomalías « positivas » son frecuentes en ellas y aumentan con la edad","Siguen siendo normales mientras no haya aparecido ningún dolor lumbar","Las anomalías son frecuentes antes de los 30 años y después se hacen raras con la edad"],["En sujetos sin ninguna queja, la resonancia lumbar encuentra habitualmente anomalías, tanto más a menudo cuanto más avanza la edad: la imagen anormal no basta por tanto para explicar un dolor.","La ausencia de queja no garantiza unas pruebas de imagen normales: es precisamente lo que el curso pone de manifiesto en esos sujetos asintomáticos.","La tendencia es la inversa: la frecuencia de esas anomalías aumenta con la edad en lugar de disminuir."]],
  "294": ["Más allá del simple plazo, ¿a qué propone el curso asociar el dolor agudo?",["A una patología en curso, como un desgarro muscular","A un retraso de la reparación tisular respecto de la recuperación habitual","A una afectación del nervio acompañada de signos neurológicos"],["El curso propone considerar el dolor agudo como el que acompaña a una patología en curso, y el ejemplo dado es el desgarro muscular.","Esa lectura es la que el curso reserva al otro extremo de la clasificación, y no al dolor agudo.","Ese cuadro corresponde a la clasificación de los dolores por su causa, y no a la relectura de la clasificación basada en la duración."]],
  "295": ["En el modelo de evolución del dolor descrito por el curso, ¿qué alimenta el catastrofismo?",["Una afectividad negativa e informaciones amenazantes sobre la enfermedad","La gravedad de la lesión inicial y su extensión constatada en las pruebas de imagen","La repetición de los episodios dolorosos y la antigüedad de la queja"],["El modelo hace converger la afectividad negativa y las informaciones amenazantes recibidas sobre la enfermedad hacia el catastrofismo.","El modelo no hace derivar el catastrofismo de la lesión ni de su imagen: parte de la experiencia dolorosa y de la forma en que se vive.","La antigüedad de la queja es un posible desenlace del circuito descrito, y no el factor que desencadena el catastrofismo."]],
  "296": ["En el modelo de evolución del dolor descrito por el curso, ¿a qué conducen la evitación y la hipervigilancia?",["Al desacondicionamiento, la depresión y la incapacidad","A una disminución de la intensidad dolorosa en cada episodio","A una extinción progresiva del miedo ligado al dolor"],["La evitación y la hipervigilancia desembocan en ese trípode, que relanza después la experiencia dolorosa y cierra el círculo.","El modelo no atribuye ningún beneficio analgésico a la evitación: describe al contrario un circuito que mantiene el dolor.","La evitación no extingue el miedo: lo mantiene, puesto que impide comprobar que el movimiento sigue siendo posible."]],
  "297": ["En el modelo de evolución del dolor descrito por el curso, ¿qué vía conduce a la recuperación tras la experiencia dolorosa?",["La ausencia de miedo, seguida de la confrontación con la actividad","El reposo estricto hasta la desaparición completa de los síntomas","La hipervigilancia, que permite vigilar los movimientos de riesgo"],["El modelo opone una rama sin miedo, que conduce a la confrontación y después a la recuperación, a la rama dominada por el miedo.","El modelo no recoge la espera pasiva como salida favorable: la evolución depende de la reacción del paciente a su dolor.","La hipervigilancia pertenece a la rama desfavorable del modelo y aleja de la recuperación."]],
  "298": ["¿Cómo se define la respuesta inflamatoria?",["Como la respuesta del sistema inmunitario a las agresiones del entorno, generada por agentes inflamatorios","Como la reacción del tejido conjuntivo al descenso del flujo sanguíneo local, desencadenada por la obstrucción de un vaso","Como la respuesta del sistema nervioso autónomo a las agresiones químicas o térmicas del entorno"],["El curso hace de la inflamación una respuesta del sistema inmunitario a las agresiones del entorno, desencadenada por agentes inflamatorios.","El descenso del flujo sanguíneo caracteriza un mecanismo isquémico; la inflamación corresponde a una respuesta inmunitaria a una agresión.","El sistema nervioso autónomo no es el actor designado: es el sistema inmunitario el que sostiene esa respuesta."]],
  "299": ["¿Mediante qué acciones se manifiesta la respuesta inflamatoria?",["Defender frente al agente nocivo, aislarlo y destruirlo, y después reparar el tejido lesionado","Diluir el agente nocivo, neutralizarlo en la sangre y después eliminarlo por vía urinaria","Aislar el agente nocivo, ralentizar el metabolismo local y después fibrosar la zona afectada"],["El curso enumera esas tres acciones: defensa frente al agente nocivo, aislamiento y destrucción del mismo, y reparación del tejido u órgano dañado.","No se describe ninguna eliminación por vía urinaria: la acción se desarrolla localmente, en el tejido agredido.","La reparación buscada atañe al propio tejido lesionado, y la fibrosis no se presenta como el desenlace esperado."]]
});
